-- Vorrats-Aufgaben (rollend-7) in bestehende Flüge einfügen: 183 Aufgaben, 11 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (3, 'terme.umformen', 777, 15, $auf$[{"l": "zusammenfassen", "t": "zusammenfassen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Fasse zusammen: 6a + 3b + 5a + 4b. Zuerst die a-Glieder, dann die b-Glieder. Das Ergebnis lautet ①a + ②b. Setzt du in dieses Ergebnis a = 2 und b = 1 ein, erhältst du ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [11, 7, 29]}, "h": "Zähle nur die Zahlen vor gleichen Buchstaben zusammen.", "w": "6 + 5 = 11 und 3 + 4 = 7. Ergebnis: 11a + 7b. Für a = 2 und b = 1: 22 + 7 = 29.", "form": "lueckenweg", "zaehlt": "nein", "r": 7778}, {"l": "zusammenfassen", "t": "zusammenfassen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Rechteck ist (3x + 4) cm lang und (x + 2) cm breit. Fasse den Umfang zuerst zu einem Term der Form ax + b zusammen und setze dann x = 6 ein. Wie viele Zentimeter beträgt der Umfang?"}, "o": {"wert": 60, "einheit": "cm"}, "h": "Der Umfang ist 2 · Länge + 2 · Breite. Fasse die x-Glieder und die Zahlen getrennt zusammen.", "w": "U = 2(3x + 4) + 2(x + 2) = 6x + 8 + 2x + 4 = 8x + 12. Für x = 6: 8 · 6 + 12 = 60 cm.", "form": "anwenden", "zaehlt": "ja", "r": 7779}, {"l": "zusammenfassen", "t": "zusammenfassen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim fasst 3x² + 5x − x² + 2x zusammen. Zeile 1: Sortieren: 3x² + 5x − x² + 2x = 3x² − x² + 5x + 2x Zeile 2: Gleichartige Glieder zusammenfassen: 3x² − x² = 2x² und 5x + 2x = 7x² Zeile 3: Ergebnis: 2x² + 7x² = 9x² In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welche Glieder sind wirklich gleichartig? Prüfe mit x = 2.", "w": "5x + 2x = 7x, nicht 7x². Beim Zusammenfassen ändert sich die Hochzahl nicht. Richtig: 2x² + 7x. Probe mit x = 2: 8 + 14 = 22, aber 2x² + 7x² = 36 ist etwas anderes.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7780}, {"l": "produkte", "t": "produkte", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vereinfache (−3a) · 4a · 2b. Das Ergebnis lautet ①a²b. Setzt du in dieses Ergebnis a = 1 und b = 2 ein, erhältst du ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-24, -48]}, "h": "Multipliziere zuerst alle Zahlen. Achte auf das Vorzeichen.", "w": "(−3) · 4 · 2 = −24. Ergebnis: −24a²b. Für a = 1 und b = 2: −24 · 1 · 2 = −48.", "form": "lueckenweg", "zaehlt": "nein", "r": 7781}, {"l": "produkte", "t": "produkte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne (−2x) · (3x) für x = 4 auf zwei Wegen. Weg A: erst vereinfachen, dann x = 4 einsetzen. Weg B: erst x = 4 einsetzen, dann malnehmen. Welchen Wert erhältst du?"}, "o": {"wert": -96}, "h": "Beide Wege müssen dasselbe ergeben. Beachte das Vorzeichen.", "w": "Weg A: (−2x) · (3x) = −6x². Für x = 4: −6 · 16 = −96. Weg B: (−8) · 12 = −96.", "form": "zwei_wege", "zaehlt": "ja", "r": 7782}, {"l": "produkte", "t": "produkte", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Für welche Zahl a gilt (−4x) · (a · x²) = 20x³ für alle Zahlen x?"}, "o": {"wert": -5}, "h": "Vergleiche die Zahlen vor x³. Was mal −4 ergibt 20?", "w": "Die Zahlen: (−4) · a = 20, also a = 20 : (−4) = −5. Die Hochzahlen passen für jedes x: x · x² = x³. Probe: (−4x) · (−5x²) = 20x³.", "form": "umkehren", "zaehlt": "ja", "r": 7783}, {"l": "minusklammer", "t": "minusklammer", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse die Klammer auf und fasse zusammen: 9x − (4x − 7) + 3. Das Ergebnis lautet ①x + ②. Setzt du in dieses Ergebnis x = 3 ein, erhältst du ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 10, 25]}, "h": "Das Minus vor der Klammer kehrt beide Vorzeichen in der Klammer um.", "w": "9x − 4x + 7 + 3 = 5x + 10. Für x = 3: 15 + 10 = 25.", "form": "lueckenweg", "zaehlt": "nein", "r": 7784}, {"l": "minusklammer", "t": "minusklammer", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne den Term 8x − (3x − 5) für x = 4 auf zwei Wegen. Weg A: erst die Klammer auflösen und zusammenfassen, dann x = 4 einsetzen. Weg B: erst x = 4 einsetzen, dann rechnen. Welchen Wert hat der Term?"}, "o": {"wert": 25}, "h": "Beide Wege müssen denselben Wert ergeben. Bei Weg A wird aus − (3x − 5) zuerst −3x + 5.", "w": "Weg A: 8x − 3x + 5 = 5x + 5. Für x = 4: 25. Weg B: 8 · 4 = 32, 3 · 4 − 5 = 7, 32 − 7 = 25.", "form": "zwei_wege", "zaehlt": "ja", "r": 7785}, {"l": "minusklammer", "t": "minusklammer", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst die Klammern auf und fasst zusammen: 6x − (2x + 5) − (x − 3). Zeile 1: 6x − (2x + 5) − (x − 3) = 6x − 2x − 5 − x − 3 Zeile 2: = (6x − 2x − x) + (−5 − 3) Zeile 3: = 3x − 8 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie ändert das Minus vor der zweiten Klammer das Vorzeichen von −3?", "w": "Vor (x − 3) steht ein Minus. Dann wird aus −3 ein +3: 6x − 2x − 5 − x + 3 = 3x − 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7786}, {"l": "ausmultiplizieren", "t": "ausmultiplizieren", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Multipliziere aus: 5(2x − 3). Das Ergebnis lautet ①x + ②. Setzt du in dieses Ergebnis x = 4 ein, erhältst du ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [10, -15, 25]}, "h": "Der Faktor vor der Klammer wird mit jedem Glied in der Klammer malgenommen.", "w": "5 · 2x = 10x und 5 · (−3) = −15. Für x = 4: 40 − 15 = 25.", "form": "lueckenweg", "zaehlt": "nein", "r": 7787}, {"l": "ausmultiplizieren", "t": "ausmultiplizieren", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt das Ausmultiplizieren. In der Kopfzeile stehen die Glieder der Klammer, links der Faktor, in der Zeile die Teilergebnisse. Welcher Term wurde ausmultipliziert?", "grafik": {"typ": "tabelle", "kopf": ["·", "2x", "−5"], "zeilen": [["3", "6x", "−15"]]}}, "a": ["3(2x + 5)", "3 · 2x − 5", "3(2x − 5)", "2(3x − 5)"], "o": {"index": 2}, "h": "Der Faktor links mal jedes Kopfglied ergibt das Feld darunter.", "w": "3 · 2x = 6x und 3 · (−5) = −15. Das passt zu 3(2x − 5) = 6x − 15.", "form": "bruecke", "zaehlt": "ja", "r": 7788}, {"l": "ausmultiplizieren", "t": "ausmultiplizieren", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Terrasse ist 3 m breit und (2x + 1) m lang. Ihre Fläche ist 3(2x + 1) m². Die Fläche soll 39 m² groß sein. Wie groß ist x?"}, "o": {"wert": 6}, "h": "Multipliziere zuerst aus. Dann hast du eine Gleichung mit x.", "w": "3(2x + 1) = 6x + 3. Aus 6x + 3 = 39 folgt 6x = 36, also x = 6. Die Terrasse ist dann 13 m lang.", "form": "anwenden", "zaehlt": "ja", "r": 7789}, {"l": "aequivalenz", "t": "aequivalenz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Sind 4(x + 2) und 4x + 2 äquivalent? Setze x = 3 ein. Der erste Term hat dann den Wert ① und der zweite den Wert ②. Die beiden Werte unterscheiden sich um ③. Also sind die Terme nicht äquivalent.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 14, 6]}, "h": "Rechne die Klammer zuerst aus. Dann erst malnehmen.", "w": "4 · 5 = 20 und 12 + 2 = 14. Der Unterschied ist 6. Wären die Terme äquivalent, kämen für jedes x gleiche Werte heraus.", "form": "lueckenweg", "zaehlt": "nein", "r": 7790}, {"l": "aequivalenz", "t": "aequivalenz", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt die Werte eines Terms für x = 1 bis 4. Welcher der Terme hat für alle vier Werte von x dieselben Werte?", "grafik": {"typ": "tabelle", "kopf": ["x", "1", "2", "3", "4"], "zeilen": [["Wert", "8", "11", "14", "17"]]}}, "a": ["3(x + 1) + 2", "3x + 2", "5x + 3", "3(x + 5)"], "o": {"index": 0}, "h": "Prüfe jeden Term mit zwei Werten von x aus der Tabelle. Ein einziger Wert reicht nicht.", "w": "3(x + 1) + 2 = 3x + 5: 8, 11, 14, 17. Das passt in allen vier Spalten. 5x + 3 liefert 8, 13, 18, 23.", "form": "bruecke", "zaehlt": "ja", "r": 7791}, {"l": "aequivalenz", "t": "aequivalenz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Für welche Zahl a haben die Terme 3(x + a) und 3x + 15 für jede Zahl x denselben Wert?"}, "o": {"wert": 5}, "h": "Multipliziere 3(x + a) aus. Dann vergleiche die Zahlen ohne x.", "w": "3(x + a) = 3x + 3a. Es muss 3a = 15 gelten, also a = 5. Probe: 3(x + 5) = 3x + 15.", "form": "umkehren", "zaehlt": "ja", "r": 7792}]$auf$::jsonb),
    (5, 'gleichungen.linear', 604, 18, $auf$[{"l": "waage", "t": "umformen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse 4x + 9 = 2x + 21. Ziehe auf beiden Seiten 2x und dann 9 ab. Dann steht 2x = ①. Also ist x = ②. Zur Probe setzt du dieses x in beide Seiten der Gleichung ein: Beide Seiten haben dann den Wert ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 6, 33]}, "h": "Mache auf beiden Seiten dasselbe. Zur Probe rechnest du die linke und die rechte Seite einzeln aus.", "w": "21 − 9 = 12, also 2x = 12 und x = 6. Probe: links 4 · 6 + 9 = 33, rechts 2 · 6 + 21 = 33. Beide Seiten sind gleich, also stimmt die Lösung.", "form": "lueckenweg", "zaehlt": "nein", "r": 7605}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Eine Waage ist im Gleichgewicht. Links liegen 4 gleiche gefüllte Dosen und ein Gewicht von 30 g. Rechts liegen 2 solche gefüllte Dosen und ein Gewicht von 90 g. Jede gefüllte Dose wiegt x g (Dose und Inhalt zusammen). Welche Gleichung gehört zur Waage?"}, "a": ["4x + 2x = 30 + 90", "4x + 30 = 2x + 90", "x + 30 = x + 90", "4x − 30 = 2x − 90"], "o": {"index": 1}, "h": "Auf jeder Seite stehen: Zahl der Dosen mal x, plus das Gewicht.", "w": "Links: 4x + 30. Rechts: 2x + 90. Gleichgewicht heißt: 4x + 30 = 2x + 90. Daraus folgt x = 30, eine gefüllte Dose wiegt also 30 g.", "form": "bruecke", "zaehlt": "ja", "r": 7606}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Die Gleichung a · x + 4 = 28 hat die Lösung x = 6. Wie groß ist die Zahl a?"}, "o": {"wert": 4}, "h": "Setze x = 6 ein. Was muss a mal 6 ergeben?", "w": "Für x = 6 gilt a · 6 + 4 = 28. Also a · 6 = 24 und a = 4. Probe: 4 · 6 + 4 = 28.", "form": "umkehren", "zaehlt": "ja", "r": 7607}, {"l": "beide_seiten", "t": "umformen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse 6x − 4 = 2x + 16. Sammle die x links und die Zahlen rechts. Dann steht dort 4x = ①. Also ist x = ②. Dann haben beide Seiten den Wert ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 5, 26]}, "h": "Die Zahl mit Minus wird durch Addieren weggeschafft.", "w": "16 + 4 = 20. 20 : 4 = 5. Probe: 6 · 5 − 4 = 26 und 2 · 5 + 16 = 26.", "form": "lueckenweg", "zaehlt": "nein", "r": 7608}, {"l": "beide_seiten", "t": "umformen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Löse 5x − 8 = 2x + 13 auf zwei Wegen. Weg A: erst 2x abziehen, sodass das x links steht. Weg B: erst 5x abziehen, sodass das x rechts steht. Welche Lösung erhältst du?"}, "o": {"wert": 7}, "h": "Beide Wege führen zur selben Lösung. Bei Weg B ist das x-Glied am Ende negativ.", "w": "Weg A: 3x − 8 = 13, 3x = 21, x = 7. Weg B: −8 = −3x + 13, −21 = −3x, x = 7. Probe: 27 = 27.", "form": "zwei_wege", "zaehlt": "ja", "r": 7609}, {"l": "beide_seiten", "t": "umformen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Tarif A kostet 6 € Grundgebühr im Monat und dazu 0,10 € je Minute. Tarif B hat keine Grundgebühr und kostet 0,16 € je Minute. Beide Tarife rechnen jede Minute einzeln ab. Bei wie vielen Minuten im Monat kosten beide Tarife gleich viel?"}, "o": {"wert": 100, "einheit": "min"}, "h": "Stelle für jeden Tarif einen Term mit der Minutenzahl x auf. Setze beide gleich.", "w": "A: 6 + 0,10x. B: 0,16x. Gleichsetzen: 6 + 0,10x = 0,16x, also 6 = 0,06x und x = 100. Probe: A 16 €, B 16 €.", "form": "anwenden", "zaehlt": "ja", "r": 7610}, {"l": "klammern", "t": "umformen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse 3(x − 2) = x + 8. Nach dem Ausmultiplizieren steht links 3x − ①. Sammelst du alle x links und die Zahlen rechts, steht dort 2x = ②. Dann ist x = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 14, 7]}, "h": "Die Zahl vor der Klammer gilt für jedes Glied in der Klammer.", "w": "3 · 2 = 6. 8 + 6 = 14. 14 : 2 = 7. Probe: 3 · 5 = 15 und 7 + 8 = 15.", "form": "lueckenweg", "zaehlt": "nein", "r": 7611}, {"l": "klammern", "t": "umformen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Löse 4(x − 3) = 2(x + 5) auf zwei Wegen. Weg A: beide Klammern gleich ausmultiplizieren. Weg B: erst beide Seiten durch 2 teilen, dann ausmultiplizieren. Wie groß ist x?"}, "o": {"wert": 11}, "h": "Beide Wege müssen dasselbe x ergeben.", "w": "Weg A: 4x − 12 = 2x + 10, 2x = 22, x = 11. Weg B: 2(x − 3) = x + 5, 2x − 6 = x + 5, x = 11. Probe: 32 = 32.", "form": "zwei_wege", "zaehlt": "ja", "r": 7612}, {"l": "klammern", "t": "umformen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst die Gleichung 2(x + 5) − 3(x − 1) = 4. Zeile 1: Klammern auflösen: 2x + 10 − 3x + 3 = 4 Zeile 2: x-Glieder zusammenfassen: 2x − 3x = x, also x + 13 = 4 Zeile 3: 13 abziehen: x = −9 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Was ergibt 2x − 3x? Setze zur Probe x = 2 ein.", "w": "2x − 3x = −x, nicht x. Richtig: −x + 13 = 4, also −x = −9 und x = 9. Probe: 2 · 14 − 3 · 8 = 4.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7613}, {"l": "probe", "t": "pruefen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Prüfe, ob x = 4 die Gleichung 5x − 4 = 2x + 5 löst. Die linke Seite hat den Wert ① und die rechte Seite den Wert ②. Die beiden Werte unterscheiden sich um ③. Also ist x = 4 keine Lösung.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [16, 13, 3]}, "h": "Setze für x überall die 4 ein. Rechne Punkt vor Strich.", "w": "Links: 20 − 4 = 16. Rechts: 8 + 5 = 13. Unterschied: 3. Die Lösung ist x = 3: 11 = 11.", "form": "lueckenweg", "zaehlt": "nein", "r": 7614}, {"l": "probe", "t": "pruefen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt die Werte der beiden Seiten der Gleichung 3x − 2 = x + 6 für einige Zahlen x. Welche Zahl ist die Lösung?", "grafik": {"typ": "tabelle", "kopf": ["x", "1", "2", "3", "4", "5"], "zeilen": [["3x − 2", "1", "4", "7", "10", "13"], ["x + 6", "7", "8", "9", "10", "11"]]}}, "a": ["x = 10", "x = 2", "x = 5", "x = 4"], "o": {"index": 3}, "h": "Suche die Spalte, in der links und rechts denselben Wert haben. Die Lösung ist die Zahl x in dieser Spalte.", "w": "Für x = 4 sind beide Seiten 10: 3 · 4 − 2 = 10 und 4 + 6 = 10. Der Wert 10 ist nicht die Lösung. Gesucht ist das x: 4.", "form": "bruecke", "zaehlt": "ja", "r": 7615}, {"l": "probe", "t": "pruefen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Die Zahl 4 ist eine Lösung der Gleichung 5x − a = 2x + 6. Wie groß ist die Zahl a?"}, "o": {"wert": 6}, "h": "Setze x = 4 ein. Dann bleibt eine Gleichung nur mit a.", "w": "Für x = 4: 20 − a = 14. Also a = 20 − 14 = 6. Probe: 5 · 4 − 6 = 14 und 2 · 4 + 6 = 14.", "form": "umkehren", "zaehlt": "ja", "r": 7616}, {"l": "sonderfaelle", "t": "pruefen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Wie viele Zahlen x erfüllen die Gleichung 2(x + 4) = 2x + 5? Nach dem Ausmultiplizieren steht links 2x + ①. Ziehst du auf beiden Seiten 2x ab, so unterscheiden sich die Zahlen links und rechts um ②. Entscheide danach: Für ③ Zahlen x ist die Gleichung erfüllt.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 3, 0]}, "h": "Die Zahl vor der Klammer gilt für jedes Glied in der Klammer. Dann zählt nur noch, ob die Zahlen übrig bleiben, die gleich sind.", "w": "2(x + 4) = 2x + 8. Nach dem Abziehen von 2x steht links 8 und rechts 5. Der Unterschied ist 3. Die beiden Zahlen sind verschieden, für kein x ist die Gleichung erfüllt, also gibt es 0 Zahlen. (Wäre der Unterschied 0, stünde links und rechts dasselbe und jede Zahl wäre eine Lösung.)", "form": "lueckenweg", "zaehlt": "nein", "r": 7617}, {"l": "sonderfaelle", "t": "pruefen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst die Gleichung 3(x − 2) + 6 = 3x. Zeile 1: Klammer auflösen: 3x − 6 − 6 = 3x Zeile 2: 3x abziehen: −12 = 0. Das stimmt für kein x. Zeile 3: Also hat die Gleichung keine Lösung. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Setze zur Probe x = 5 ein. Stimmt die Gleichung?", "w": "3(x − 2) = 3x − 6. Dann steht 3x − 6 + 6 = 3x, also 0 = 0. Die Gleichung stimmt für jedes x. Probe mit x = 5: 15 = 15.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7618}, {"l": "sonderfaelle", "t": "pruefen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Zahl a gilt die Gleichung 2(3x − 1) = 6x + a für jede Zahl x?"}, "o": {"wert": -2}, "h": "Multipliziere die linke Seite aus. Dann muss die Zahl ohne x auf beiden Seiten gleich sein.", "w": "2(3x − 1) = 6x − 2. Damit beide Seiten gleich sind, muss a = −2 sein.", "form": "umkehren", "zaehlt": "ja", "r": 7619}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ben hat 50 € und spart jede Woche 4 €. Mia hat 20 € und spart jede Woche 10 €. Nach w Wochen haben beide gleich viel: 50 + 4w = 20 + 10w. Sortiere so, dass die w auf der rechten Seite und die Zahlen auf der linken Seite stehen. Dann steht dort ① = ②w. Also ist w = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [30, 6, 5]}, "h": "Auf jeder Seite wird derselbe Term abgezogen: erst 4w, dann 20.", "w": "Links 50 − 20 = 30, rechts 10w − 4w = 6w. Also 30 = 6w und w = 5. Nach 5 Wochen haben beide 70 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 7620}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Handwerker verlangt 35 € für die Anfahrt und 42 € für jede Stunde Arbeit. Die Rechnung beträgt 245 €. Mit x sind die Arbeitsstunden gemeint. Welche Gleichung gehört zur Rechnung?"}, "a": ["35 + 42x = 245", "35x + 42 = 245", "(35 + 42)x = 245", "35 + 42 + x = 245"], "o": {"index": 0}, "h": "Die Anfahrt zahlst du einmal. Der Stundenlohn gilt für jede Stunde.", "w": "Anfahrt 35 € plus x Stunden zu 42 €: 35 + 42x = 245. Daraus folgt 42x = 210 und x = 5 Stunden.", "form": "bruecke", "zaehlt": "ja", "r": 7621}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Kerze ist 30 cm hoch und brennt gleichmäßig 2 cm in jeder Stunde ab. Eine zweite Kerze ist 24 cm hoch und brennt gleichmäßig 1 cm in jeder Stunde ab. Beide werden gleichzeitig angezündet. Nach wie vielen Stunden sind beide Kerzen gleich hoch?"}, "o": {"wert": 6, "einheit": "Stunden"}, "h": "Stelle für jede Kerze einen Term mit der Stundenzahl x auf. Beide Höhen sollen gleich sein.", "w": "Kerze 1: 30 − 2x. Kerze 2: 24 − x. Gleichsetzen: 30 − 2x = 24 − x, also 6 = x. Nach 6 Stunden sind beide 18 cm hoch.", "form": "anwenden", "zaehlt": "ja", "r": 7622}]$auf$::jsonb),
    (7, 'groessen.indirekt', 651, 21, $auf$[{"l": "erkennen", "t": "erkennen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Alle Helfer arbeiten gleich schnell. 3 Helfer brauchen 24 Stunden, 6 Helfer brauchen 12 Stunden. Bei einer indirekten Proportionalität ist das Produkt aus Helfern und Stunden immer gleich. Dieses Produkt ist ①. Dann brauchen 4 Helfer ② Stunden und 9 Helfer ③ Stunden.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [72, 18, 8]}, "h": "Rechne Helfer mal Stunden. Teile dieses Produkt durch die neue Zahl der Helfer.", "w": "3 · 24 = 72 und 6 · 12 = 72. 72 : 4 = 18 und 72 : 9 = 8.", "form": "lueckenweg", "zaehlt": "nein", "r": 7652}, {"l": "erkennen", "t": "erkennen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt, wie lange verschiedene Zahlen von Helfern für eine Arbeit brauchen. Alle Helfer arbeiten gleich schnell. Welche Aussage passt?", "grafik": {"typ": "tabelle", "kopf": ["Helfer", "2", "4", "8"], "zeilen": [["Stunden", "12", "6", "3"]]}}, "a": ["Indirekt proportional: Das Produkt ist immer 24.", "Direkt proportional: Der Quotient ist immer gleich.", "Indirekt proportional: Die Differenz ist immer gleich.", "Weder noch: Die Zeiten werden kleiner."], "o": {"index": 0}, "h": "Bilde für jede Spalte das Produkt aus Helfern und Stunden.", "w": "2 · 12 = 24, 4 · 6 = 24, 8 · 3 = 24. Das Produkt ist immer gleich. Die Zuordnung ist indirekt proportional.", "form": "bruecke", "zaehlt": "ja", "r": 7653}, {"l": "erkennen", "t": "erkennen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft, ob die Zuordnung Arbeiter → Tage indirekt proportional ist: 2 Arbeiter brauchen 30 Tage, 5 Arbeiter brauchen 12 Tage, 10 Arbeiter brauchen 7 Tage. Zeile 1: Ich prüfe, ob das Produkt aus Arbeitern und Tagen immer gleich ist. Zeile 2: Die Produkte sind 2 · 30 = 60, 5 · 12 = 60 und 10 · 7 = 70. Zeile 3: 60, 60 und 70 sind fast gleich, also ist die Zuordnung indirekt proportional. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Muss das Produkt genau gleich sein oder reicht „fast“?", "w": "Bei einer indirekten Proportionalität muss das Produkt immer genau gleich sein. 70 ist nicht 60. Die Zuordnung ist nicht indirekt proportional.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7654}, {"l": "vervielfachen", "t": "erkennen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zuordnung Pumpen → Stunden ist indirekt proportional (alle Pumpen leisten gleich viel). 4 Pumpen brauchen 24 Stunden. Doppelt so viele Pumpen brauchen nur die Hälfte der Zeit: 8 Pumpen brauchen ① Stunden. Verdoppelst du die Pumpenzahl noch einmal auf 16, halbiert sich die Zeit aus ① noch einmal: 16 Pumpen brauchen ② Stunden. Zur Probe rechnest du 16 mal ②. Das Ergebnis ist ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 6, 96]}, "h": "Mehr Pumpen: Die Zeit wird durch denselben Faktor geteilt. Das Produkt aus Pumpen und Stunden bleibt gleich.", "w": "8 Pumpen: 24 : 2 = 12 Stunden. 16 Pumpen: 12 : 2 = 6 Stunden. Probe: 16 · 6 = 96 und 4 · 24 = 96. Das Produkt bleibt gleich.", "form": "lueckenweg", "zaehlt": "nein", "r": 7655}, {"l": "vervielfachen", "t": "erkennen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "6 Maler streichen ein Haus in 20 Tagen. Alle Maler arbeiten gleich schnell, und die Arbeit lässt sich beliebig aufteilen. Wie viele Tage brauchen 8 Maler? Rechne auf zwei Wegen. Weg A: erst ausrechnen, wie lange ein Maler braucht. Weg B: Die Zahl der Maler wächst um den Faktor 8/6, deshalb ändert sich die Zeit um den Faktor 6/8."}, "o": {"wert": 15, "einheit": "Tage"}, "h": "Beide Wege müssen dasselbe ergeben. Mehr Maler: Die Zeit wird kürzer.", "w": "Weg A: 1 Maler braucht 6 · 20 = 120 Tage, 8 Maler brauchen 120 : 8 = 15 Tage. Weg B: Die Malerzahl wächst um den Faktor 8/6, die Zeit ändert sich um den Faktor 6/8: 20 · 6/8 = 15 Tage.", "form": "zwei_wege", "zaehlt": "ja", "r": 7656}, {"l": "vervielfachen", "t": "erkennen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "10 gleich starke Pumpen leeren ein Becken in 12 Stunden. Jede Pumpe fördert gleichmäßig. Es soll in nur 8 Stunden leer sein. Wie viele solche Pumpen braucht man mindestens?"}, "o": {"wert": 15, "einheit": "Pumpen"}, "h": "Das Produkt aus Pumpen und Stunden bleibt gleich. Rechne zurück von der Zeit zur Zahl der Pumpen.", "w": "10 · 12 = 120 Pumpenstunden. 120 : 8 = 15. Man braucht 15 Pumpen.", "form": "umkehren", "zaehlt": "ja", "r": 7657}, {"l": "produkt", "t": "erkennen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Tabelle gehört zu einer indirekten Proportionalität. Für x = 5 ist y = 12. Das Produkt x · y ist ①. Für x = 4 ist dann y = ②. Für x = 20 ist y = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [60, 15, 3]}, "h": "Das Produkt aus x und y bleibt immer gleich. Teile es durch das neue x.", "w": "5 · 12 = 60. 60 : 4 = 15. 60 : 20 = 3.", "form": "lueckenweg", "zaehlt": "nein", "r": 7658}, {"l": "produkt", "t": "erkennen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Rechteck soll immer die Fläche 36 cm² haben. Die Zuordnung Breite → Länge ist dann indirekt proportional. Wie lang ist das Rechteck, wenn es 4 cm breit ist?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Die Fläche ist Breite mal Länge. Sie bleibt gleich.", "w": "Breite · Länge = 36. Bei 4 cm Breite: Länge = 36 : 4 = 9 cm.", "form": "anwenden", "zaehlt": "ja", "r": 7659}, {"l": "produkt", "t": "erkennen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Bei einer indirekten Proportionalität ist y = 7,5, wenn x = 8 ist. Für welches x ist y = 12?"}, "o": {"wert": 5}, "h": "Berechne zuerst das Produkt aus x und y.", "w": "x · y = 8 · 7,5 = 60. Für y = 12 gilt x = 60 : 12 = 5. Probe: 5 · 12 = 60.", "form": "umkehren", "zaehlt": "ja", "r": 7660}, {"l": "dreisatz", "t": "rechnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "5 gleiche Rohre füllen einen Tank in 36 Minuten. Jedes Rohr liefert gleich viel Wasser. Wie viele Minuten brauchen 9 solche Rohre? Rechne auf zwei Wegen. Weg A: erst ausrechnen, wie lange 1 Rohr braucht. Weg B: Das Produkt aus Rohren und Minuten bleibt gleich."}, "o": {"wert": 20, "einheit": "min"}, "h": "Beide Wege müssen dasselbe ergeben. Mehr Rohre: kürzere Zeit.", "w": "Weg A: 1 Rohr braucht 5 · 36 = 180 Minuten, 9 Rohre brauchen 180 : 9 = 20 Minuten. Weg B: 5 · 36 = 180 = 9 · 20.", "form": "zwei_wege", "zaehlt": "ja", "r": 7661}, {"l": "dreisatz", "t": "rechnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "12 Arbeiter brauchen für eine Arbeit 10 Tage. Alle Arbeiter sind gleich leistungsfähig, und die Arbeit lässt sich beliebig aufteilen. Es sind aber nur 8 Arbeiter da. Welcher Weg führt zur richtigen Zahl der Tage?"}, "a": ["10 : 12 · 8 ≈ 6,7 Tage.", "12 − 8 = 4 Arbeiter weniger, also 10 + 4 = 14 Tage.", "10 · 8 = 80 Tage.", "12 · 10 = 120 Arbeitertage, dann 120 : 8 = 15 Tage."], "o": {"index": 3}, "h": "Weniger Arbeiter: Die Arbeit dauert länger. Was bleibt gleich?", "w": "Die gesamte Arbeit ist 12 · 10 = 120 Arbeitertage. Mit 8 Arbeitern: 120 : 8 = 15 Tage.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 7662}, {"l": "dreisatz", "t": "rechnen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Vorrat Hundefutter reicht für 4 Hunde genau 15 Tage. Jeder Hund bekommt jeden Tag dieselbe Menge. Nach 3 Tagen kommen 2 Hunde dazu, es sind jetzt 6 Hunde. Wie viele Tage reicht der Rest des Futters noch?"}, "o": {"wert": 8, "einheit": "Tage"}, "h": "Wie viel Futter ist nach 3 Tagen noch da? Rechne in „Hundetagen“.", "w": "Noch da: 12 Tage für 4 Hunde, das sind 4 · 12 = 48 Hundetage. 48 : 6 = 8. Der Rest reicht noch 8 Tage.", "form": "anwenden", "zaehlt": "ja", "r": 7663}, {"l": "graph", "t": "darstellen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Im Koordinatensystem ist der Punkt P(3 | 8) eingezeichnet. Er liegt auf dem Graphen einer indirekten Proportionalität (für x > 0). Das Produkt x · y ist für jeden Punkt dieses Graphen gleich: ①. Der Graph geht durch den Punkt Q(4 | ②). Er geht auch durch den Punkt R(12 | ③).", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ).", "grafik": {"typ": "koordinaten", "x": [0, 13], "y": [0, 13], "punkte": [{"x": 3, "y": 8, "name": "P"}]}}, "o": {"werte": [24, 6, 2]}, "h": "Das Produkt der Koordinaten von P gilt für alle Punkte des Graphen. Teile es durch die x-Koordinate.", "w": "x · y = 3 · 8 = 24. Für Q: 24 : 4 = 6. Für R: 24 : 12 = 2. Je größer x, desto kleiner y.", "form": "lueckenweg", "zaehlt": "nein", "r": 7664}, {"l": "graph", "t": "darstellen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Der Graph zeigt eine indirekt proportionale Zuordnung und den Punkt P(3 | 4). Welche Gleichung gehört zum Graphen?", "grafik": {"typ": "koordinaten", "x": [0, 13], "y": [0, 13], "graphen": [{"art": "hyperbel", "a": 12, "b": 0, "c": 0, "name": "f"}], "punkte": [{"x": 3, "y": 4, "name": "P"}]}}, "a": ["y = x : 12", "y = 12 : x", "y = 12 · x", "y = x + 1"], "o": {"index": 1}, "h": "Setze die Koordinaten von P in die Gleichungen ein. Passt mehr als eine Gleichung? Dann lies einen zweiten Punkt des Graphen ab und prüfe, ob x · y gleich bleibt.", "w": "Für P(3 | 4) gilt x · y = 12. Also y = 12 : x. Probe: 12 : 3 = 4. Auch y = x + 1 geht durch P, aber der Graph geht durch den Punkt (6 | 2), und dort ist x + 1 = 7. Nur bei y = 12 : x bleibt x · y immer gleich.", "form": "bruecke", "zaehlt": "ja", "r": 7665}, {"l": "graph", "t": "darstellen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Der Punkt P(4 | 6) liegt auf dem Graphen einer indirekten Proportionalität. Der Punkt Q(x | 2) liegt auf demselben Graphen. Welche x-Koordinate hat Q?"}, "o": {"wert": 12}, "h": "Berechne das Produkt der Koordinaten von P. Es ist für jeden Punkt des Graphen gleich.", "w": "x · y = 4 · 6 = 24. Für Q: x · 2 = 24, also x = 12. Probe: 12 · 2 = 24.", "form": "umkehren", "zaehlt": "ja", "r": 7666}, {"l": "unterscheiden", "t": "darstellen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Wie prüfst du sicher, ob eine Wertetabelle zu einer indirekten Proportionalität gehört?"}, "a": ["Es reicht, dass y kleiner wird, wenn x größer wird.", "Alle Produkte x · y müssen gleich sein.", "Alle Quotienten y : x müssen gleich sein.", "Alle Summen x + y müssen gleich sein."], "o": {"index": 1}, "h": "Denke an die Helfer-Aufgabe: Doppelt so viele Helfer, halb so lange. Was bleibt gleich?", "w": "Bei einer indirekten Proportionalität ist x · y immer derselbe Wert. „Wird kleiner“ gilt auch für andere Zuordnungen, zum Beispiel y = 20 − x.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 7667}, {"l": "unterscheiden", "t": "darstellen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt, wie viel verschiedene Mengen Äpfel kosten. Welche Zuordnung passt?", "grafik": {"typ": "tabelle", "kopf": ["Menge in kg", "2", "4", "6"], "zeilen": [["Preis in €", "5", "10", "15"]]}}, "a": ["Indirekt proportional: Der Preis wird größer.", "Indirekt proportional: Das Produkt ist immer gleich.", "Weder noch, weil die Zahlen verschieden sind.", "Direkt proportional: Der Quotient Preis : Menge ist immer 2,5."], "o": {"index": 3}, "h": "Prüfe Quotient und Produkt in jeder Spalte.", "w": "5 : 2 = 2,5; 10 : 4 = 2,5; 15 : 6 = 2,5. Der Quotient ist immer gleich, also direkt proportional. Die Produkte 10, 40, 90 sind verschieden.", "form": "bruecke", "zaehlt": "ja", "r": 7668}, {"l": "unterscheiden", "t": "darstellen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim ordnet eine Taxifahrt ein. Der Preis besteht aus 3 € Grundgebühr und 2 € je Kilometer. 2 km kosten 7 €, 4 km kosten 11 €. Zeile 1: Wenn die Strecke größer wird, wird auch der Preis größer. Also ist die Zuordnung direkt proportional. Zeile 2: Dann kosten 8 km das Vierfache von 2 km: 4 · 7 = 28 €. Zeile 3: Die Fahrt von 8 km kostet 28 €. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Reicht „mehr gibt mehr“ für direkte Proportionalität? Prüfe: Kosten 4 km doppelt so viel wie 2 km?", "w": "Direkt proportional heißt: doppelte Strecke, doppelter Preis. Hier ist 11 € nicht 14 €. Die Zuordnung ist nicht proportional. 8 km kosten 3 + 16 = 19 €.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7669}, {"l": "sach", "t": "rechnen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Die Miete für eine Hütte wird gleichmäßig auf alle Personen verteilt, die Gesamtmiete bleibt gleich. Bei 8 Personen zahlt jede Person 45 €. Zwei Personen sagen ab. Wie viel Euro muss jede der übrigen Personen zahlen?"}, "o": {"wert": 60, "einheit": "€"}, "h": "Wie hoch ist die gesamte Miete? Sie ändert sich nicht.", "w": "Gesamtmiete: 8 · 45 = 360 €. Jetzt 6 Personen: 360 : 6 = 60 €.", "form": "anwenden", "zaehlt": "ja", "r": 7670}, {"l": "sach", "t": "rechnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Futtervorrat reicht für 15 Schafe 24 Tage. Jedes Schaf frisst jeden Tag dieselbe Menge. Wie viele Tage reicht er für 20 Schafe? Rechne auf zwei Wegen. Weg A: Der Vorrat ist 15 · 24 „Schaftage“; teile durch 20. Weg B: Die Schafzahl wird mit 20/15 malgenommen, die Tage mit 15/20."}, "o": {"wert": 18, "einheit": "Tage"}, "h": "Beide Wege müssen dasselbe ergeben. Mehr Schafe: weniger Tage.", "w": "Weg A: 15 · 24 = 360 Schaftage, 360 : 20 = 18 Tage. Weg B: 24 · 3/4 = 18 Tage.", "form": "zwei_wege", "zaehlt": "ja", "r": 7671}, {"l": "sach", "t": "rechnen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Zwei gleiche Pumpen füllen ein Becken in 9 Stunden. Jede Pumpe fördert gleichmäßig. Nach 3 Stunden fällt eine Pumpe aus. Die andere pumpt allein weiter. Wie viele Stunden dauert das Füllen insgesamt?"}, "o": {"wert": 15, "einheit": "Stunden"}, "h": "Rechne in Pumpenstunden: Wie viel ist insgesamt nötig, wie viel ist nach 3 Stunden getan?", "w": "Insgesamt nötig: 2 · 9 = 18 Pumpenstunden. Nach 3 Stunden: 2 · 3 = 6 getan. Rest: 12 Pumpenstunden mit einer Pumpe: 12 Stunden. Insgesamt 3 + 12 = 15 Stunden.", "form": "anwenden", "zaehlt": "ja", "r": 7672}]$auf$::jsonb),
    (20, 'gleichungen.bruch', 660, 21, $auf$[{"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bestimme die Definitionsmenge von 7/(2x − 10) = 1/(3x + 12). Setze jeden Nenner gleich 0. Der erste Nenner ist 0 für x = ①. Der zweite Nenner ist 0 für x = ②. Das Produkt dieser beiden verbotenen Zahlen ist ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, -4, -20]}, "h": "Löse jede Nenner-Gleichung wie eine Waage.", "w": "2x − 10 = 0 ergibt x = 5. 3x + 12 = 0 ergibt x = −4. 5 · (−4) = −20. D = ℚ \\ {−4; 5}.", "form": "lueckenweg", "zaehlt": "nein", "r": 7661}, {"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Welche dieser Gleichungen hat die Definitionsmenge ℚ \\ {−5; 2}?"}, "a": ["3/(x + 2) = 7/(x − 5)", "3/(x − 2) = 7/x", "3/(x − 2) = (x + 5)/7", "3/(x − 2) = 7/(x + 5)"], "o": {"index": 3}, "h": "Welche Zahl macht welchen Nenner zu 0? Das müssen genau −5 und 2 sein.", "w": "x − 2 ist 0 für x = 2. x + 5 ist 0 für x = −5. Nur die Gleichung 3/(x − 2) = 7/(x + 5) schließt genau diese beiden Zahlen aus.", "form": "umkehren", "zaehlt": "ja", "r": 7662}, {"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst die Definitionsmenge von 5/(x² − 4) = 1 bestimmen. Welcher Weg ist richtig?"}, "a": ["Den Nenner gleich 0 setzen: x² − 4 = 0 hat die Lösungen 2 und −2. Beide werden ausgeschlossen.", "Den Nenner gleich 0 setzen: x² − 4 = 0 führt zu x = 2. Nur 2 wird ausgeschlossen.", "Den Zähler gleich 0 setzen: 5 ist nie 0, also wird keine Zahl ausgeschlossen.", "Die Gleichung zuerst lösen und die Lösung ausschließen."], "o": {"index": 0}, "h": "Die Definitionsmenge steht fest, bevor du die Gleichung löst. Was darf im Nenner nie herauskommen?", "w": "x² − 4 = 0 gilt für x = 2 und für x = −2. Beide Zahlen machen den Nenner zu 0. D = ℚ \\ {−2; 2}.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 7663}, {"l": "ein_bruch", "t": "ein_bruch", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse 48/(3x) = 2 (x ≠ 0). Kürze zuerst den Bruch links mit 3. Der Zähler des gekürzten Bruchs ist ①. Dann ist x = ②. Der Nenner 3x hat für dieses x den Wert ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [16, 8, 24]}, "h": "Aus dem gekürzten Bruch folgt: mit x multiplizieren, dann durch die Zahl rechts teilen.", "w": "48 : 3 = 16. Aus 16/x = 2 folgt 16 = 2x und x = 8. Probe: 48/24 = 2.", "form": "lueckenweg", "zaehlt": "nein", "r": 7664}, {"l": "ein_bruch", "t": "ein_bruch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Löse 18/x = 3 (x ≠ 0) auf zwei Wegen. Weg A: beide Seiten mit x multiplizieren und dann durch 3 teilen. Weg B: auf beiden Seiten den Kehrwert bilden und dann mit 18 malnehmen. Wie groß ist x?"}, "o": {"wert": 6}, "h": "Beide Wege müssen dasselbe x ergeben.", "w": "Weg A: 18 = 3x, also x = 6. Weg B: x/18 = 1/3, also x = 18 · 1/3 = 6. Probe: 18 : 6 = 3.", "form": "zwei_wege", "zaehlt": "ja", "r": 7665}, {"l": "ein_bruch", "t": "ein_bruch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Wasserhahn füllt einen Eimer mit 90 Litern in x Minuten. Dabei fließen gleichmäßig 90/x Liter in jeder Minute. Es sollen 15 Liter in jeder Minute fließen. Wie viele Minuten dauert das Füllen?"}, "o": {"wert": 6, "einheit": "min"}, "h": "Stelle die Gleichung 90/x = 15 auf. Multipliziere dann mit x.", "w": "90/x = 15 ergibt 90 = 15x und x = 6. Das Füllen dauert 6 Minuten.", "form": "anwenden", "zaehlt": "ja", "r": 7666}, {"l": "ueber_kreuz", "t": "ueber_kreuz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse 6/(x + 1) = 4/(x − 1) (x ≠ −1 und x ≠ 1). Du multiplizierst über Kreuz und sortierst: die x links und die Zahlen rechts. Dann steht dort 2x = ①. Also ist x = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [10, 5]}, "h": "Über Kreuz: Zähler links mal Nenner rechts, Zähler rechts mal Nenner links.", "w": "6(x − 1) = 4(x + 1), also 6x − 6 = 4x + 4. Dann 2x = 10 und x = 5. Probe: 6/6 = 1 und 4/4 = 1.", "form": "lueckenweg", "zaehlt": "nein", "r": 7667}, {"l": "ueber_kreuz", "t": "ueber_kreuz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Die Gleichung 6/(x + a) = 2/(x − 1) hat die Lösung x = 3. Wie groß ist die Zahl a?"}, "o": {"wert": 3}, "h": "Setze x = 3 ein und rechne die rechte Seite aus. Dann steht links 6/(3 + a) = dieser Wert.", "w": "Rechts: 2/(3 − 1) = 1. Links: 6/(3 + a) = 1, also 3 + a = 6 und a = 3. Probe: 6/6 = 1.", "form": "umkehren", "zaehlt": "ja", "r": 7668}, {"l": "ueber_kreuz", "t": "ueber_kreuz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst 5/(x + 2) = 3/(x − 4) (x ≠ −2 und x ≠ 4). Zeile 1: Über Kreuz: 5(x − 4) = 3(x + 2) Zeile 2: Ausmultiplizieren: 5x − 20 = 3x + 6 Zeile 3: Sortieren: 2x = 26 Zeile 4: Teilen: x = 26 · 2 = 52 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Wie bekommst du x allein, wenn 2x = 26 dasteht? Mach die Probe.", "w": "2x = 26 heißt: durch 2 teilen. x = 13. Probe: 5/15 = 1/3 und 3/9 = 1/3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7669}, {"l": "hauptnenner", "t": "hauptnenner", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse 3/(2x) + 1/(3x) = 22/48 (x ≠ 0). Der Hauptnenner der linken Seite ist ①x. Erweitert hat der erste Bruch dann den Zähler ②. Der Zähler der Summe der beiden erweiterten Brüche ist ③. Setze die Summe gleich 22/48 und multipliziere über Kreuz. Dann ist x = ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 9, 11, 4]}, "h": "Der Hauptnenner ist das kleinste gemeinsame Vielfache von 2 und 3, mal x. Über Kreuz: Zähler mal Nenner der anderen Seite.", "w": "HN = 6x. 3/(2x) = 9/(6x) und 1/(3x) = 2/(6x). Summe: 11/(6x). Aus 11/(6x) = 22/48 folgt 11 · 48 = 22 · 6x, also 528 = 132x und x = 4. Probe: 3/8 + 1/12 = 9/24 + 2/24 = 11/24 = 22/48.", "form": "lueckenweg", "zaehlt": "nein", "r": 7670}, {"l": "hauptnenner", "t": "hauptnenner", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Löse 1/x + 1/(2x) = 3/2 (x ≠ 0) auf zwei Wegen. Weg A: erst die Brüche links zusammenfassen. Weg B: beide Seiten sofort mit dem Hauptnenner 2x multiplizieren. Wie groß ist x?"}, "o": {"wert": 1}, "h": "Beide Wege müssen dasselbe x ergeben.", "w": "Weg A: 2/(2x) + 1/(2x) = 3/(2x) = 3/2, also 2x = 2 und x = 1. Weg B: 2 + 1 = 3x, also x = 1.", "form": "zwei_wege", "zaehlt": "ja", "r": 7671}, {"l": "hauptnenner", "t": "hauptnenner", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Eine Pumpe füllt ein Becken allein in x Stunden. Eine zweite Pumpe braucht allein 2x Stunden. Beide Pumpen fördern gleichmäßig. Zusammen füllen sie das Becken in 4 Stunden. Welche Gleichung gehört dazu (x ≠ 0)?"}, "a": ["x + 2x = 4", "1/x + 1/(2x) = 4", "1/x + 1/(2x) = 1/4", "1/x · 1/(2x) = 1/4"], "o": {"index": 2}, "h": "Was schafft jede Pumpe in einer Stunde? Diese Anteile werden addiert.", "w": "Pumpe 1 schafft 1/x je Stunde, Pumpe 2 schafft 1/(2x). Zusammen 1/4 je Stunde. Daraus folgt 3/(2x) = 1/4 und x = 6.", "form": "bruecke", "zaehlt": "ja", "r": 7672}, {"l": "scheinloesung", "t": "scheinloesung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse (3x − 1)/(2x − 8) = 11/(2x − 8). Beide Seiten haben denselben Nenner. Multipliziere mit diesem Nenner und sortiere: 3x = ①. Der einzige Kandidat ist dann x = ②. Für diese Zahl hat der Nenner 2x − 8 den Wert ③. Die Gleichung hat ④ Lösungen.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 4, 0, 0]}, "h": "Aus gleichen Nennern folgt: Die Zähler müssen gleich sein. Prüfe den Kandidaten in den ursprünglichen Nennern. Gehört er zur Definitionsmenge?", "w": "3x − 1 = 11 ergibt 3x = 12 und den Kandidaten x = 4. Der Nenner ist 2 · 4 − 8 = 0. Die Zahl 4 liegt nicht in der Definitionsmenge, sie ist nur ein Kandidat und keine Lösung. Es gibt 0 Lösungen: L = { }.", "form": "lueckenweg", "zaehlt": "nein", "r": 7673}, {"l": "scheinloesung", "t": "scheinloesung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst x/(x − 2) = 2/(x − 2) mit der Definitionsmenge ℚ \\ {2}. Zeile 1: Mit (x − 2) multiplizieren: x = 2 Zeile 2: Die Zahl 2 gehört zur Lösung, weil die Rechnung x = 2 ergeben hat. Zeile 3: Also ist L = {2}. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Für x = 2 ist der Nenner x − 2 gleich …? Darf man dann einsetzen?", "w": "Für x = 2 ist der Nenner 0. Die Zahl 2 liegt nicht in der Definitionsmenge. Sie ist eine Scheinlösung. Richtig: L = { }.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7674}, {"l": "scheinloesung", "t": "scheinloesung", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Zahl a ist x = 3 bei der Gleichung (x + a)/(x − 3) = 7/(x − 3) eine Scheinlösung? Beim Lösen kommt dabei x = 3 heraus."}, "o": {"wert": 4}, "h": "Wenn nach dem Multiplizieren x = 3 herauskommt, gilt x + a = 7 für x = 3.", "w": "Nach dem Multiplizieren mit (x − 3) steht x + a = 7. Mit x = 3 folgt a = 4. Dann ist 3 eine Scheinlösung, denn der Nenner ist 0.", "form": "umkehren", "zaehlt": "ja", "r": 7675}, {"l": "verhaeltnis", "t": "verhaeltnis", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse x : 8 = 15 : 12. Über Kreuz multipliziert steht links 12x. Rechts steht ①. Dann ist x = ②. Das Verhältnis x : 8 lässt sich mit diesem x zu ③ : 4 kürzen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [120, 10, 5]}, "h": "Das Produkt der Außenglieder ist gleich dem Produkt der Innenglieder.", "w": "Außenglieder sind x und 12, Innenglieder sind 8 und 15. Es gilt 12x = 8 · 15 = 120, also x = 10. Dann ist 10 : 8 = 5 : 4.", "form": "lueckenweg", "zaehlt": "nein", "r": 7676}, {"l": "verhaeltnis", "t": "verhaeltnis", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt ein Rezept. Für 450 g Mehl soll die Wassermenge x bestimmt werden. Welche Verhältnisgleichung gehört dazu?", "grafik": {"typ": "tabelle", "kopf": ["", "Mehl", "Wasser"], "zeilen": [["Rezept", "300 g", "180 ml"], ["gesucht", "450 g", "x"]]}}, "a": ["x : 450 = 300 : 180", "x : 300 = 180 : 450", "x : 450 = 180 : 300", "x · 450 = 180 · 300"], "o": {"index": 2}, "h": "Gleiche Stoffe stehen in beiden Verhältnissen an derselben Stelle.", "w": "x : 450 = 180 : 300. Über Kreuz: 300x = 450 · 180 = 81 000, also x = 270. Man braucht 270 ml Wasser.", "form": "bruecke", "zaehlt": "ja", "r": 7677}, {"l": "verhaeltnis", "t": "verhaeltnis", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Auf einer Karte sind 3 cm in Wirklichkeit 12 km. Eine Wanderstrecke ist in Wirklichkeit 50 km lang. Wie viele Zentimeter lang ist sie auf der Karte?"}, "o": {"wert": 12.5, "einheit": "cm"}, "h": "Stelle eine Verhältnisgleichung auf: Kartenlänge zu Wirklichkeit ist immer gleich.", "w": "x : 50 = 3 : 12. Über Kreuz: 12x = 150, also x = 12,5. Die Strecke ist 12,5 cm lang.", "form": "anwenden", "zaehlt": "ja", "r": 7678}, {"l": "graphisch", "t": "graphisch", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du löst 36/x = 4 (x ≠ 0) mit einer Wertetabelle. Für x = 3 hat 36/x den Wert ①. Für x = 18 hat 36/x den Wert ②. Der gesuchte Wert 4 liegt dazwischen und ist doppelt so groß wie ②. Bei dieser Zuordnung halbiert sich dann x gegenüber 18. Die Lösung ist x = ③. Von x = 3 bis zur Lösung wächst x um ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 2, 9, 6]}, "h": "Teile 36 durch den x-Wert. Ist der gesuchte Wert doppelt so groß wie der Wert bei x = 18, so wird x halbiert.", "w": "36 : 3 = 12 und 36 : 18 = 2. Der gesuchte Wert 4 ist das Doppelte von 2, also wird x von 18 auf die Hälfte 9 verkleinert. Probe: 36 : 9 = 4. Die Lösung ist x = 9. Von x = 3 bis 9 wächst x um 6.", "form": "lueckenweg", "zaehlt": "nein", "r": 7679}, {"l": "graphisch", "t": "graphisch", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Zeichnung zeigt zwei Graphen. Sie gehören zu den beiden Seiten einer Gleichung. Welche Gleichung wird mit dem Schnittpunkt gelöst?", "grafik": {"typ": "koordinaten", "x": [-7, 7], "y": [-6, 6], "graphen": [{"art": "hyperbel", "a": 8, "b": 0, "c": 0, "name": "y = 8/x"}, {"art": "linear", "m": 0, "t": 2, "name": "y = 2"}]}}, "a": ["8/x = 2", "8/x = x", "2/x = 8", "8/x + 2 = 0"], "o": {"index": 0}, "h": "Eine Seite ist die Hyperbel, die andere die waagrechte Gerade. Lies ihre Gleichungen ab.", "w": "Die Hyperbel gehört zu y = 8/x, die Gerade zu y = 2. Gleichsetzen: 8/x = 2. Der Schnittpunkt liegt bei x = 4.", "form": "bruecke", "zaehlt": "ja", "r": 7680}, {"l": "graphisch", "t": "graphisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Löse 12/(x + 2) = 4 (x ≠ −2) auf zwei Wegen. Weg A: rechnerisch, indem du mit dem Nenner multiplizierst. Weg B: mit einer Wertetabelle, in der du x-Werte ausprobierst. Wie groß ist x?"}, "o": {"wert": 1}, "h": "Beide Wege müssen dasselbe x ergeben.", "w": "Weg A: 12 = 4(x + 2), also x + 2 = 3 und x = 1. Weg B: Für x = 1 ist 12/3 = 4. Probe stimmt.", "form": "zwei_wege", "zaehlt": "ja", "r": 7681}]$auf$::jsonb),
    (31, 'stochastik.grundbegriffe', 590, 9, $auf$[{"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In einer Urne liegen 6 rote, 2 blaue, 3 grüne und 2 gelbe Kugeln. Man zieht eine Kugel und notiert die Farbe. Der Ergebnisraum hat ① Ergebnisse. Zum Ereignis „rot oder blau“ gehören ② Kugeln. In der Urne liegen insgesamt ③ Kugeln. Zum Gegenereignis „weder rot noch blau“ gehören ④ Kugeln.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 8, 13, 5]}, "h": "Die Ergebnisse sind die Farben. Das Ereignis fasst Ergebnisse zusammen, gezählt werden aber die Kugeln. Das Gegenereignis besteht aus allen übrigen Kugeln.", "w": "Vier Farben, also vier Ergebnisse. Rot oder blau: 6 + 2 = 8 Kugeln. Insgesamt 6 + 2 + 3 + 2 = 13 Kugeln. Gegenereignis: 13 − 8 = 5 Kugeln (3 grüne und 2 gelbe).", "form": "lueckenweg", "zaehlt": "nein", "r": 7591}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Würfel hat die Zahlen 1 bis 12. Das Ereignis „Die Zahl ist ein Vielfaches von k“ hat genau 4 Ergebnisse. Dabei ist k eine natürliche Zahl größer als 1. Welche Zahl ist k?"}, "o": {"wert": 3}, "h": "Zähle für k = 2, 3, 4 … wie viele Vielfache es zwischen 1 und 12 gibt.", "w": "Vielfache von 3: 3, 6, 9, 12. Das sind genau 4. Bei k = 2 sind es 6, bei k = 4 nur 3 Vielfache.", "form": "umkehren", "zaehlt": "ja", "r": 7592}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Glücksrad hat 8 gleich große Felder mit den Zahlen 1 bis 8. Wie viele Ergebnisse gehören zum Ereignis „Die Zahl ist durch 2 oder durch 3 teilbar“?"}, "o": {"wert": 5, "einheit": "Ergebnisse"}, "h": "Gehe die Zahlen 1 bis 8 der Reihe nach durch. Eine Zahl zählt nur einmal, auch wenn sie in beiden Reihen vorkommt.", "w": "Durch 2 teilbar: 2, 4, 6, 8. Durch 3 teilbar: 3 und 6. Die 6 gehört zu beiden. Zusammen 5 Ergebnisse: {2; 3; 4; 6; 8}.", "form": "anwenden", "zaehlt": "ja", "r": 7593}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Münze wird 40-mal geworfen. Wappen fällt 18-mal. Wie groß ist die relative Häufigkeit von Wappen in Prozent? Rechne auf zwei Wegen. Weg A: 18 : 40 als Dezimalzahl und dann mal 100. Weg B: den Bruch 18/40 zuerst kürzen und dann auf den Nenner 100 erweitern."}, "o": {"wert": 45, "einheit": "%"}, "h": "Beide Wege müssen dasselbe Ergebnis ergeben.", "w": "Weg A: 18 : 40 = 0,45 und 0,45 · 100 = 45. Weg B: 18/40 = 9/20 = 45/100 = 45 %.", "form": "zwei_wege", "zaehlt": "ja", "r": 7594}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt 50 Würfe mit einem Würfel. Wie groß ist die relative Häufigkeit der Sechs?", "grafik": {"typ": "tabelle", "kopf": ["Zahl", "1", "2", "3", "4", "5", "6"], "zeilen": [["Anzahl", "9", "7", "8", "12", "6", "8"]]}}, "a": ["8", "0,16", "0,08", "0,125"], "o": {"index": 1}, "h": "Relative Häufigkeit = Anzahl der Sechsen : Anzahl aller Würfe.", "w": "In der Spalte „6“ steht 8. Es gab 50 Würfe. 8 : 50 = 0,16.", "form": "bruecke", "zaehlt": "ja", "r": 7595}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Qualitätskontrolle prüft 250 Schrauben. 15 davon sind fehlerhaft. Es werden 2000 Schrauben hergestellt. Wie viele davon sind nach dieser Kontrolle ungefähr fehlerhaft?"}, "o": {"wert": 120, "einheit": "Schrauben"}, "h": "Berechne zuerst die relative Häufigkeit der fehlerhaften Schrauben. Übertrage sie auf 2000.", "w": "15 : 250 = 0,06 = 6 %. 6 % von 2000 sind 120. Es sind ungefähr 120 fehlerhafte Schrauben.", "form": "anwenden", "zaehlt": "ja", "r": 7596}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Urne enthält Kugeln mit den Nummern 1 bis n. Man zieht zweimal nacheinander eine Kugel und legt sie nach jedem Zug zurück. Das Baumdiagramm hat insgesamt 36 Wege. Wie viele Kugeln liegen in der Urne?"}, "o": {"wert": 6}, "h": "Jede Stufe hat n Äste. Wie viele Wege gibt es bei zwei Stufen?", "w": "Es gibt n · n Wege, weil jeder der n Äste der ersten Stufe wieder n Zweige hat. n · n = 36, also n = 6.", "form": "umkehren", "zaehlt": "ja", "r": 7597}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein normaler Würfel wird zweimal geworfen. Ein Ergebnis ist ein Zahlenpaar (erster Wurf | zweiter Wurf). Wie viele Ergebnisse gehören zum Ereignis „Die Augensumme ist 5 oder 9“? Rechne auf zwei Wegen. Weg A: mit einem Baumdiagramm. Weg B: mit einer Tabelle mit 6 Zeilen und 6 Spalten."}, "o": {"wert": 8, "einheit": "Ergebnisse"}, "h": "Zähle die Paare getrennt für Summe 5 und für Summe 9.", "w": "Summe 5: (1|4), (2|3), (3|2), (4|1). Summe 9: (3|6), (4|5), (5|4), (6|3). Zusammen 4 + 4 = 8 Ergebnisse.", "form": "zwei_wege", "zaehlt": "ja", "r": 7598}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Glücksrad mit den Zahlen 1, 2 und 3 wird zweimal gedreht. Die Tabelle zeigt alle neun Augensummen. Wie viele Ergebnisse gehören zum Ereignis „Die Summe ist größer als 4“?", "grafik": {"typ": "tabelle", "kopf": ["+", "1", "2", "3"], "zeilen": [["1", "2", "3", "4"], ["2", "3", "4", "5"], ["3", "4", "5", "6"]]}}, "a": ["6", "3", "2", "9"], "o": {"index": 1}, "h": "Zähle die Felder der Tabelle, in denen die Summe 5 oder 6 steht.", "w": "Summe 5 steht zweimal, Summe 6 einmal. Zusammen 3 Ergebnisse.", "form": "bruecke", "zaehlt": "ja", "r": 7599}]$auf$::jsonb),
    (34, 'terme.bruchterme', 666, 21, $auf$[{"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bestimme über ℚ die Definitionsmenge des Bruchs mit dem Zähler 9 und dem Nenner (3x − 12)(2x + 10). Ein Produkt ist 0, wenn ein Faktor 0 ist. Der erste Faktor ist 0 für x = ①. Der zweite Faktor ist 0 für x = ②. Zählst du beide ausgeschlossenen Zahlen zusammen, erhältst du ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, -5, -1]}, "h": "Setze jeden Faktor einzeln gleich 0 und löse wie eine Waage.", "w": "3x − 12 = 0 ergibt x = 4. 2x + 10 = 0 ergibt x = −5. Beide Zahlen werden ausgeschlossen: D = ℚ \\ {−5; 4}. Ihre Summe ist 4 + (−5) = −1.", "form": "lueckenweg", "zaehlt": "nein", "r": 7667}, {"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Welcher dieser Terme hat die Definitionsmenge ℚ \\ {−3}?"}, "a": ["5/(x − 3)", "(x + 3)/5", "5/(x + 3)", "5/(3x)"], "o": {"index": 2}, "h": "Für welche Zahl wird der Nenner 0? Das ist die ausgeschlossene Zahl.", "w": "Bei 5/(x + 3) ist der Nenner 0, wenn x = −3 ist. Nur dort ist der Term nicht definiert.", "form": "umkehren", "zaehlt": "ja", "r": 7668}, {"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Klasse mietet einen Bus für 504 €. Zwei Schüler zahlen nichts. Bei n Schülern in der Klasse (n ist eine ganze Zahl) zahlt jeder der anderen 504/(n − 2) €. Für welche Schülerzahl n lässt sich dieser Preis nicht berechnen?"}, "o": {"wert": 2}, "h": "Wann ist der Nenner n − 2 gleich 0?", "w": "n − 2 = 0 gilt für n = 2. Dann zahlt niemand, und der Term hat keinen Sinn. Für n = 30 wären es 504 : 28 = 18 € je Schüler.", "form": "anwenden", "zaehlt": "ja", "r": 7669}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne T(5) für T(x) = (x² − 1)/(x − 1) (x ≠ 1). Der Zähler hat für x = 5 den Wert ①. Der Nenner hat den Wert ②. Dann ist T(5) = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [24, 4, 6]}, "h": "Setze für x überall 5 ein. Rechne bei x² erst das Quadrat.", "w": "Zähler: 25 − 1 = 24. Nenner: 4. 24 : 4 = 6.", "form": "lueckenweg", "zaehlt": "nein", "r": 7670}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne T(5) für T(x) = (x² − 9)/(x − 3) (x ≠ 3) auf zwei Wegen. Weg A: erst x = 5 einsetzen, dann ausrechnen. Weg B: erst kürzen (x² − 9 ist (x − 3)(x + 3)), dann x = 5 einsetzen. Welchen Wert hat T(5)?"}, "o": {"wert": 8}, "h": "Beide Wege müssen denselben Wert ergeben.", "w": "Weg A: (25 − 9) : (5 − 3) = 16 : 2 = 8. Weg B: Nach dem Kürzen bleibt x + 3 = 8.", "form": "zwei_wege", "zaehlt": "ja", "r": 7671}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt einige Werte eines Terms T(x). Welcher Term passt zu allen Werten der Tabelle?", "grafik": {"typ": "tabelle", "kopf": ["x", "1", "2", "3", "5"], "zeilen": [["T(x)", "6", "4", "3", "2"]]}}, "a": ["12/x", "6/x", "12/(x + 1)", "12/(x + 2)"], "o": {"index": 2}, "h": "Setze die x-Werte aus der Tabelle in die Terme ein und vergleiche.", "w": "12/(1 + 1) = 6, 12/(2 + 1) = 4, 12/(3 + 1) = 3, 12/(5 + 1) = 2. Das passt zur Tabelle.", "form": "bruecke", "zaehlt": "ja", "r": 7672}, {"l": "kuerzen", "t": "kuerzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Kürze (8x + 8)/(12x + 12) für x ≠ −1. Beide Summen haben den Faktor (x + 1) und lassen sich damit kürzen, solange x ≠ −1 ist. Übrig bleibt ein Zahlenbruch. Der größte gemeinsame Teiler von Zähler und Nenner dieses Zahlenbruchs ist ①. Der vollständig gekürzte Bruch ist ②/③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 2, 3]}, "h": "Klammere zuerst in Zähler und Nenner den Faktor aus.", "w": "8x + 8 = 8(x + 1) und 12x + 12 = 12(x + 1). Es bleibt 8/12. Der größte gemeinsame Teiler ist 4. 8/12 = 2/3. Das gilt für x ≠ −1, denn für x = −1 ist der ursprüngliche Nenner 0.", "form": "lueckenweg", "zaehlt": "nein", "r": 7673}, {"l": "kuerzen", "t": "kuerzen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim kürzt den Bruch (x² + 4x)/(x² + 2x) für x ≠ 0 und x ≠ −2. Zeile 1: Zähler x(x + 4), Nenner x(x + 2). Zeile 2: Mit x gekürzt: (x + 4)/(x + 2). Zeile 3: Mit x gekürzt: 4/2 = 2. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Darf man aus einer Summe kürzen? Probe mit x = 2.", "w": "Aus Summen darf man nicht kürzen. (x + 4)/(x + 2) bleibt stehen, weiterhin mit x ≠ 0 und x ≠ −2. Probe mit x = 2: 6/4, nicht 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7674}, {"l": "kuerzen", "t": "kuerzen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für alle Zahlen x, bei denen der Nenner nicht 0 ist, gilt (x² − 25)/(x + a) = x − 5. Welche Zahl ist a?"}, "o": {"wert": 5}, "h": "Zerlege x² − 25 in zwei Klammern. Eine davon muss im Nenner stehen.", "w": "x² − 25 = (x − 5)(x + 5). Zum Kürzen muss der Nenner x + 5 sein, also a = 5. Probe: (x − 5)(x + 5) : (x + 5) = x − 5. Das gilt nur für x ≠ −5, denn für x = −5 ist der ursprüngliche Nenner 0.", "form": "umkehren", "zaehlt": "ja", "r": 7675}, {"l": "erweitern", "t": "erweitern", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Erweitere 3/(2x) (x ≠ 0) so, dass der Nenner 10x² wird. Der Erweiterungsfaktor ist ①x. Der neue Zähler ist ②x.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 15]}, "h": "Welche Zahl mal 2 ergibt 10? Und welche Variable fehlt zu x²?", "w": "Der Faktor ist 5x, denn 2x · 5x = 10x². Neuer Zähler: 3 · 5x = 15x. Der Bruch ist 15x/(10x²).", "form": "lueckenweg", "zaehlt": "nein", "r": 7676}, {"l": "erweitern", "t": "erweitern", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt einen Bruch vor und nach dem Erweitern (x ≠ 0). Womit wurde der Bruch erweitert?", "grafik": {"typ": "tabelle", "kopf": ["", "Zähler", "Nenner"], "zeilen": [["vorher", "5", "2x"], ["nachher", "15x", "6x²"]]}}, "a": ["mit 3x", "mit 3", "mit x", "mit 3x²"], "o": {"index": 0}, "h": "Teile den neuen Zähler durch den alten. Prüfe dann den Nenner.", "w": "15x : 5 = 3x und 6x² : 2x = 3x. Der Bruch wurde mit 3x erweitert.", "form": "bruecke", "zaehlt": "ja", "r": 7677}, {"l": "erweitern", "t": "erweitern", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Die Brüche 2/(x + 1) und 3/(x − 1) (x ≠ −1 und x ≠ 1) sollen gleiche Nenner bekommen. Welcher Weg ist richtig?"}, "a": ["Beide Brüche mit (x + 1) erweitern. Dann sind beide Nenner gleich.", "Die Nenner addieren: 2x ist der gemeinsame Nenner.", "Nur den ersten Bruch mit (x − 1) erweitern.", "Den ersten Bruch mit (x − 1) erweitern, den zweiten mit (x + 1). Beide Nenner sind dann (x + 1)(x − 1)."], "o": {"index": 3}, "h": "Jeder Bruch braucht den Nenner des anderen zusätzlich. Mit was musst du also jeweils erweitern?", "w": "Erster Bruch: Zähler 2(x − 1), Nenner (x + 1)(x − 1). Zweiter Bruch: Zähler 3(x + 1), Nenner (x + 1)(x − 1). Jetzt stimmen die Nenner überein.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 7678}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Fasse zusammen: 1/(4x) + 1/(6x) (x ≠ 0). Der Hauptnenner ist ①x. Erweitert hat der erste Bruch dann den Zähler ② und der zweite den Zähler ③. Der Zähler der Summe ist ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 3, 2, 5]}, "h": "Welche kleinste Zahl kommt in der Viererreihe und in der Sechserreihe vor?", "w": "Hauptnenner 12x. 1/(4x) = 3/(12x) und 1/(6x) = 2/(12x). Summe: 5/(12x).", "form": "lueckenweg", "zaehlt": "nein", "r": 7679}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne T(2) für T(x) = 12/x + 6/(x + 1) (x ≠ 0 und x ≠ −1) auf zwei Wegen. Weg A: erst x = 2 einsetzen, dann beide Brüche addieren. Weg B: erst zu einem Bruch zusammenfassen, dann x = 2 einsetzen. Welchen Wert hat T(2)?"}, "o": {"wert": 8}, "h": "Beide Wege müssen dasselbe ergeben. Weg A ist kürzer.", "w": "Weg A: 12/2 + 6/3 = 6 + 2 = 8. Weg B: (18x + 12)/(x² + x) = 48/6 = 8.", "form": "zwei_wege", "zaehlt": "ja", "r": 7680}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 2, "g": "einkleidung", "y": "luecken", "f": {"text": "Ein Radfahrer fährt 24 km mit v km/h hin und 24 km mit (v + 4) km/h zurück (v > 0). Die Gesamtzeit ist 24/v + 24/(v + 4) Stunden. Fasse zu einem Bruch mit dem Nenner v² + 4v zusammen. Der Zähler lautet ①v + ②. Für v = 8 erhältst du die Gesamtzeit, indem du diesen Zähler durch den Nenner teilst: ③ Stunden.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [48, 96, 5]}, "h": "Erweitere den ersten Bruch mit (v + 4) und den zweiten mit v. Fasse dann die Zähler zusammen.", "w": "24(v + 4) + 24v = 24v + 96 + 24v = 48v + 96. Die Gesamtzeit ist (48v + 96)/(v² + 4v). Für v = 8: 480 : 96 = 5 Stunden. Probe: 24/8 + 24/12 = 3 + 2 = 5.", "form": "anwenden", "zaehlt": "ja", "r": 7681}, {"l": "multiplizieren", "t": "multiplizieren", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne und kürze für x ≠ 0: (4x/9) · (3/(8x)). Vor dem Kürzen steht oben ①x und unten ②x. Gekürzt ergibt sich der Bruch ③/④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 72, 1, 6]}, "h": "Multipliziere oben mit oben und unten mit unten. Kürze dann mit dem gemeinsamen Faktor.", "w": "12x/(72x). Der gemeinsame Faktor ist 12x, er ist für x ≠ 0 nicht 0. 12x : 12x = 1 und 72x : 12x = 6. Ergebnis: 1/6 (für x ≠ 0).", "form": "lueckenweg", "zaehlt": "nein", "r": 7682}, {"l": "multiplizieren", "t": "multiplizieren", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst (x + 2)/5 · 10/(x + 2) für x ≠ −2 berechnen. Welcher Weg führt zum richtigen Ergebnis?"}, "a": ["Zähler addieren und Nenner multiplizieren: (x + 12)/(5x + 10).", "Zähler und Nenner durch denselben Faktor teilen, der nicht 0 ist: durch (x + 2) und durch 5. Ergebnis: 2 für x ≠ −2.", "Mit dem Kehrwert des zweiten Bruchs malnehmen: (x + 2)²/50.", "Nur die Zahlen kürzen: 10 : 5 = 2. Den Faktor (x + 2) aus dem Nenner mit dem aus dem Zähler malnehmen. Ergebnis: 2(x + 2)²."], "o": {"index": 1}, "h": "Gekürzt wird, indem man Zähler und Nenner durch denselben Faktor teilt, der nicht 0 ist.", "w": "(x + 2)/5 · 10/(x + 2): Zähler und Nenner werden durch (x + 2) geteilt (erlaubt, weil x ≠ −2 ist) und 10 : 5 = 2. Ergebnis 2 für x ≠ −2.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 7683}, {"l": "multiplizieren", "t": "multiplizieren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet (6/x) · (x²/3) für x ≠ 0. Zeile 1: Ich nehme den Kehrwert des zweiten Bruchs: (6/x) · (3/x²) Zeile 2: Zähler mal Zähler: 6 · 3 = 18. Nenner mal Nenner: x · x² = x³ Zeile 3: Ergebnis: 18/x³ In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wann nimmt man den Kehrwert? Prüfe mit x = 3.", "w": "Beim Malnehmen gibt es keinen Kehrwert. Richtig: Zähler 6 · x² = 6x², Nenner x · 3 = 3x, also 6x²/(3x) = 2x für x ≠ 0. Probe mit x = 3: (6/3) · (9/3) = 6 und 2x = 6.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7684}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Wie prüfst du am besten, ob die Umformung (x + 3)/(x + 5) = 3/5 für alle x ≠ −5 stimmt?"}, "a": ["Das x streichen. Es bleibt 3/5 übrig, also stimmt die Umformung.", "Eine Zahl einsetzen, zum Beispiel x = 1: links 4/6, rechts 3/5. Die Werte sind verschieden, also ist die Umformung falsch.", "Nur x = 0 einsetzen: links 3/5, rechts 3/5. Die Werte sind gleich, also stimmt die Umformung immer.", "Zähler und Nenner jeweils durch 3 teilen. Dann stimmt es."], "o": {"index": 1}, "h": "Ein Gegenbeispiel reicht, um eine Umformung zu widerlegen. Ein einziges passendes Beispiel beweist aber noch nichts.", "w": "Für x = 1 ist (1 + 3)/(1 + 5) = 4/6 und 3/5 ist etwas anderes. Damit ist die Umformung widerlegt. x = 0 war zufällig ein Fall, in dem beide Seiten gleich sind.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 7685}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie groß ist T(7) für T(x) = (4x + 12)/(x + 3) (x ≠ −3)? Rechne auf zwei Wegen. Weg A: x = 7 gleich einsetzen. Weg B: erst im Zähler 4 ausklammern, mit (x + 3) kürzen und dann x = 7 einsetzen."}, "o": {"wert": 4}, "h": "Beide Wege müssen dasselbe ergeben.", "w": "Weg A: (28 + 12)/(7 + 3) = 40/10 = 4. Weg B: 4(x + 3)/(x + 3) = 4. Der Term ist immer 4, solange x ≠ −3 ist.", "form": "zwei_wege", "zaehlt": "ja", "r": 7686}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim behauptet, dass vier Umformungen für alle erlaubten Zahlen stimmen. Die Zeilen sind unabhängig voneinander. Zeile 1: (5x + 10)/5 = x + 2 Zeile 2: (x² − 9)/(x − 3) = x + 3 Zeile 3: 6/x + 3/x = 9/x Zeile 4: (x + 4)/(x + 6) = 4/6 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Prüfe Zeile für Zeile mit einer Zahl, zum Beispiel x = 2.", "w": "Bei (x + 4)/(x + 6) darf man x nicht streichen, denn x steht in einer Summe. Für x = 2 ist der Wert 6/8, aber 4/6 ist etwas anderes.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7687}]$auf$::jsonb),
    (72, 'terme.quadratische_extreme', 390, 15, $auf$[{"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ergänze x² − 10x zu einem vollständigen Quadrat der Form (x + ①)². Dafür musst du zuerst ② addieren. Es gilt dann x² − 10x + ② = (x + ①)².", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-5, 25]}, "h": "Nimm die Hälfte der Zahl vor x. Die Ergänzung ist deren Quadrat.", "w": "Die Hälfte von −10 ist −5. (−5)² = 25. Also x² − 10x + 25 = (x − 5)².", "form": "lueckenweg", "zaehlt": "nein", "r": 7391}, {"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Für welche positive Zahl b gilt x² + bx + 36 = (x + c)² für alle Zahlen x, mit einem positiven c?"}, "o": {"wert": 12}, "h": "Zerlege 36 als Quadrat: c · c = 36. Das mittlere Glied ist das doppelte Produkt.", "w": "c² = 36, also c = 6. Dann ist b = 2 · 6 = 12. Probe: (x + 6)² = x² + 12x + 36.", "form": "umkehren", "zaehlt": "ja", "r": 7392}, {"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim bringt T(x) = x² + 8x + 3 in die Scheitelform. Zeile 1: Die Hälfte von 8 ist 4, und 4² = 16. Zeile 2: x² + 8x + 16 = (x + 4)² Zeile 3: Also ist T(x) = (x + 4)² + 3. Zeile 4: Der Scheitel ist S(−4 | 3). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Du hast 16 addiert. Was musst du dann tun, damit der Term derselbe bleibt? Prüfe mit x = 0.", "w": "Die addierte 16 muss wieder abgezogen werden: T(x) = (x + 4)² + 3 − 16 = (x + 4)² − 13. Probe mit x = 0: 16 − 13 = 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7393}, {"l": "scheitelform", "t": "scheitelform", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bringe x² + 6x + 4 mit quadratischer Ergänzung in die Form (x + ①)² − ②. Du addierst eine Zahl und ziehst sie wieder ab.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 5]}, "h": "Die Zahl in der Klammer ist die Hälfte der Zahl vor x. Das Quadrat davon wird addiert und abgezogen.", "w": "x² + 6x + 9 − 9 + 4 = (x + 3)² − 5. Probe mit x = 0: 9 − 5 = 4.", "form": "lueckenweg", "zaehlt": "nein", "r": 7394}, {"l": "scheitelform", "t": "scheitelform", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt einige Werte von T(x) = x² − 6x + 5. Welche Scheitelform gehört zu diesem Term?", "grafik": {"typ": "tabelle", "kopf": ["x", "1", "2", "3", "4", "5"], "zeilen": [["T(x)", "0", "−3", "−4", "−3", "0"]]}}, "a": ["(x − 3)² + 4", "(x + 3)² − 4", "(x − 5)² − 4", "(x − 3)² − 4"], "o": {"index": 3}, "h": "Der tiefste Wert der Tabelle liegt in der Mitte. Seine x-Stelle steht in der Klammer, sein Wert dahinter.", "w": "Der kleinste Wert −4 steht bei x = 3. Die Scheitelform ist (x − 3)² − 4. Probe: (x − 3)² − 4 = x² − 6x + 9 − 4 = x² − 6x + 5.", "form": "bruecke", "zaehlt": "ja", "r": 7395}, {"l": "scheitelform", "t": "scheitelform", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne T(7) für T(x) = x² − 6x + 5 auf zwei Wegen. Weg A: x = 7 direkt einsetzen. Weg B: zuerst in die Scheitelform (x − 3)² − 4 umformen, dann x = 7 einsetzen. Welchen Wert erhältst du?"}, "o": {"wert": 12}, "h": "Beide Wege müssen denselben Wert ergeben.", "w": "Weg A: 49 − 42 + 5 = 12. Weg B: (7 − 3)² − 4 = 16 − 4 = 12.", "form": "zwei_wege", "zaehlt": "ja", "r": 7396}, {"l": "extremwert", "t": "extremwert", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bestimme das Minimum von T(x) = x² − 8x + 19. Die Scheitelform lautet (x − ①)² + ②. Setzt du x = 6 in diese Form ein, erhältst du den Wert ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 3, 7]}, "h": "Halbiere die Zahl vor x. Das Quadrat davon ziehst du von 19 ab.", "w": "x² − 8x + 16 − 16 + 19 = (x − 4)² + 3. Das Minimum 3 liegt bei x = 4. Für x = 6: 4 + 3 = 7.", "form": "lueckenweg", "zaehlt": "nein", "r": 7397}, {"l": "extremwert", "t": "extremwert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Ball wird geworfen. Seine Höhe in Metern nach t Sekunden ist h(t) = −t² + 6t + 1 (für t von 0 bis 6). Wie hoch kommt der Ball höchstens?"}, "o": {"wert": 10, "einheit": "m"}, "h": "Bringe h(t) in die Scheitelform. Wegen des Minuszeichens vor t² ist der Scheitel ein Maximum.", "w": "−t² + 6t + 1 = −(t − 3)² + 10. Das Maximum 10 liegt bei t = 3. Der Ball kommt höchstens 10 m hoch.", "form": "anwenden", "zaehlt": "ja", "r": 7398}, {"l": "extremwert", "t": "extremwert", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Funktion T(x) = (x − 3)² + c hat das Minimum 7. Welchen Wert hat T(5)?"}, "o": {"wert": 11}, "h": "Das Minimum von (x − 3)² + c ist c. Wo liegt das Minimum?", "w": "Das Minimum ist c = 7. Dann ist T(5) = (5 − 3)² + 7 = 4 + 7 = 11.", "form": "umkehren", "zaehlt": "ja", "r": 7399}, {"l": "mit_faktor", "t": "mit_faktor", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bestimme das Minimum von T(x) = 2x² − 12x + 22. Klammere 2 bei den ersten beiden Gliedern aus: 2(x² − ①x) + 22. Ergänze in der Klammer: 2(x − ②)² − ③ + 22. Das Minimum ist ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 3, 18, 4]}, "h": "Die ergänzte Zahl steht in der Klammer und wird mit dem Faktor vor der Klammer malgenommen.", "w": "2x² − 12x = 2(x² − 6x) = 2((x − 3)² − 9) = 2(x − 3)² − 18. Dazu 22: 2(x − 3)² + 4. Das Minimum ist 4 bei x = 3.", "form": "lueckenweg", "zaehlt": "nein", "r": 7400}, {"l": "mit_faktor", "t": "mit_faktor", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Bestimme das Minimum von T(x) = 2x² − 12x + 22 auf zwei Wegen. Weg A: Faktor ausklammern und quadratisch ergänzen. Weg B: T(2), T(3) und T(4) ausrechnen. Weil T(2) und T(4) gleich sind, liegt die Symmetrieachse der Parabel in der Mitte bei x = 3. Die Parabel öffnet sich nach oben, weil vor x² die positive Zahl 2 steht. Also ist der kleinste dieser drei Werte das Minimum. Wie groß ist das Minimum?"}, "o": {"wert": 4}, "h": "Beide Wege müssen dasselbe Minimum ergeben.", "w": "Weg A: 2(x − 3)² + 4, Minimum 4. Weg B: T(2) = 6, T(3) = 4, T(4) = 6. Wegen T(2) = T(4) liegt die Symmetrieachse bei x = 3. Die Parabel öffnet sich nach oben (Faktor 2 vor x² ist positiv), also ist 4 der kleinste Funktionswert, der Minimalwert von T für alle x. Der tiefste Punkt der Parabel ist (3|4).", "form": "zwei_wege", "zaehlt": "ja", "r": 7401}, {"l": "mit_faktor", "t": "mit_faktor", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim bestimmt das Minimum von T(x) = 3x² + 12x + 5. Zeile 1: 3x² + 12x + 5 = 3(x² + 4x) + 5 Zeile 2: Die Hälfte von 4 ist 2: 3((x + 2)² − 4) + 5 Zeile 3: Klammer auflösen: 3(x + 2)² − 12 + 5 = 3(x + 2)² − 7 Zeile 4: Das Minimum ist −7 bei x = 2. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Die Klammer heißt (x + 2)². Bei welchem x ist sie 0?", "w": "Aus (x + 2)² = 0 folgt x = −2. Das Minimum −7 liegt bei x = −2. Probe: T(−2) = 12 − 24 + 5 = −7.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7402}, {"l": "optimierung", "t": "optimierung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Rechteck hat den Umfang 20 m. Eine Seite ist x lang. Die andere Seite ist ① − x. Die Fläche A(x) = x · (① − x) ist am größten bei x = ②. Dann ist die Fläche ③ m².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [10, 5, 25]}, "h": "Die beiden Seiten zusammen sind der halbe Umfang. Die Fläche ist am größten, wenn beide Seiten gleich lang sind.", "w": "Halber Umfang 10. Andere Seite 10 − x. A(x) = −x² + 10x = −(x − 5)² + 25. Maximum bei x = 5, Fläche 25 m².", "form": "lueckenweg", "zaehlt": "nein", "r": 7403}, {"l": "optimierung", "t": "optimierung", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Bauer hat 24 m Zaun. Er umzäunt ein Rechteck an einer Hauswand, sodass nur drei Seiten Zaun brauchen. Die Wand ist länger als der Zaun. Die beiden Seiten senkrecht zur Wand sind je x lang. Welcher Term gibt die Fläche des Rechtecks an?"}, "a": ["x(24 − x)", "x(24 − 2x)", "x(24 − 4x)", "2x + (24 − 2x)"], "o": {"index": 1}, "h": "Die Seite parallel zur Wand ist der Rest des Zauns nach Abzug der beiden Seiten x.", "w": "Die Seite an der Wand ist 24 − 2x lang. Fläche: A = x · (24 − 2x) = −2x² + 24x.", "form": "bruecke", "zaehlt": "ja", "r": 7404}, {"l": "optimierung", "t": "optimierung", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Schülerfirma verkauft Kerzen. Bei dem Preis von p Euro je Kerze werden 80 − 10p Kerzen in der Woche verkauft (p liegt zwischen 0 und 8). Die Wocheneinnahmen sind p · (80 − 10p). Bei welchem Preis in Euro sind die Einnahmen am größten?"}, "o": {"wert": 4, "einheit": "€"}, "h": "Multipliziere aus: −10p² + 80p. Klammere −10 aus und ergänze quadratisch.", "w": "p(80 − 10p) = −10p² + 80p = −10(p − 4)² + 160. Das Maximum liegt bei p = 4. Dann sind die Einnahmen 160 €.", "form": "anwenden", "zaehlt": "ja", "r": 7405}]$auf$::jsonb),
    (94, 'messen.prisma_zylinder', 411, 21, $auf$[{"l": "prisma_volumen", "t": "prisma_volumen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein gerades Prisma hat als Grundfläche ein Dreieck mit der Grundseite 9 cm und der zugehörigen Höhe 4 cm. Das Prisma ist 15 cm hoch. Die Grundfläche ist ① cm² groß. Das Volumen ist ② cm³.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [18, 270]}, "h": "Die Grundfläche des Dreiecks ist die Hälfte von Grundseite mal Höhe. Das Volumen ist Grundfläche mal Körperhöhe.", "w": "G = 9 · 4 : 2 = 18 cm². V = 18 · 15 = 270 cm³.", "form": "lueckenweg", "zaehlt": "nein", "r": 7412}, {"l": "prisma_volumen", "t": "prisma_volumen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein gerades Prisma hat als Grundfläche ein rechtwinkliges Dreieck mit den Katheten 6 cm und 5 cm. Das Prisma ist 8 cm hoch. Berechne das Volumen auf zwei Wegen. Weg A: Grundfläche des Dreiecks mal Körperhöhe. Weg B: Zwei solche Prismen ergeben zusammen einen Quader mit den Kanten 6 cm, 5 cm und 8 cm, das Prisma ist also die Hälfte davon. Wie groß ist das Volumen?"}, "o": {"wert": 120, "einheit": "cm³"}, "h": "Beide Wege müssen dasselbe Volumen ergeben.", "w": "Weg A: G = 6 · 5 : 2 = 15 cm², V = 15 · 8 = 120 cm³. Weg B: Der Quader hat 6 · 5 · 8 = 240 cm³, die Hälfte ist 120 cm³.", "form": "zwei_wege", "zaehlt": "ja", "r": 7413}, {"l": "prisma_volumen", "t": "prisma_volumen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zelt hat die Form eines liegenden geraden Prismas. Die Grundfläche ist ein Dreieck, die Zeltöffnung: 4 m breit und 2,5 m hoch. Das Zelt ist 6 m lang. Wie viel Kubikmeter Luft passen in das Zelt?"}, "o": {"wert": 30, "einheit": "m³"}, "h": "Die Öffnung ist die Grundfläche, die Länge des Zelts ist die Körperhöhe.", "w": "G = 4 · 2,5 : 2 = 5 m². V = 5 · 6 = 30 m³. Es passen 30 m³ Luft hinein.", "form": "anwenden", "zaehlt": "ja", "r": 7414}, {"l": "prisma_oberflaeche", "t": "prisma_oberflaeche", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein gerades Prisma hat als Grundfläche ein Rechteck mit den Seiten 3 cm und 4 cm. Es ist 10 cm hoch. Die Grundfläche ist ① cm². Der Mantel ist ein Rechteck mit der Höhe 10 cm und dem Umfang der Grundfläche als Länge. Er ist ② cm² groß. Die Oberfläche ist ③ cm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 140, 164]}, "h": "Die Oberfläche besteht aus zwei Grundflächen und dem Mantel.", "w": "G = 12 cm². Umfang 14 cm, Mantel 14 · 10 = 140 cm². O = 2 · 12 + 140 = 164 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 7415}, {"l": "prisma_oberflaeche", "t": "prisma_oberflaeche", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt alle Teilflächen des Netzes eines geraden Dreiecksprismas. Wie groß ist die Oberfläche?", "grafik": {"typ": "tabelle", "kopf": ["Teil des Netzes", "Anzahl", "Fläche je Stück"], "zeilen": [["Dreieck", "2", "6 cm²"], ["Rechteck 3 cm × 10 cm", "1", "30 cm²"], ["Rechteck 4 cm × 10 cm", "1", "40 cm²"], ["Rechteck 5 cm × 10 cm", "1", "50 cm²"]]}}, "a": ["126 cm²", "120 cm²", "252 cm²", "132 cm²"], "o": {"index": 3}, "h": "Rechne Anzahl mal Fläche je Stück für jede Zeile und addiere.", "w": "2 · 6 = 12 cm². Mantel: 30 + 40 + 50 = 120 cm². O = 12 + 120 = 132 cm².", "form": "bruecke", "zaehlt": "ja", "r": 7416}, {"l": "prisma_oberflaeche", "t": "prisma_oberflaeche", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet die Oberfläche eines geraden Prismas mit einem Quadrat als Grundfläche. Die Seite des Quadrats ist 5 cm lang, die Körperhöhe des Prismas ist 8 cm. Zeile 1: Grundfläche: 5 · 5 = 25 cm². Zeile 2: Mantel: Umfang der Grundfläche 4 · 5 = 20 cm, mal die Körperhöhe 8 cm = 160 cm². Zeile 3: Oberfläche: Mantel plus eine Grundfläche, also 160 + 25 = 185 cm². In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wie viele Grundflächen hat ein Prisma?", "w": "Ein Prisma hat zwei Grundflächen: Grund- und Deckfläche. O = 2 · 25 + 160 = 210 cm².", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7417}, {"l": "prisma_umstellen", "t": "prisma_umstellen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein gerades Prisma hat das Volumen 720 cm³ und die Grundfläche 48 cm². Die Höhe ist ① cm. Ein zweites gerades Prisma hat dieselbe Grundfläche und die doppelte Höhe. Seine Höhe ist ② cm und sein Volumen ③ cm³.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [15, 30, 1440]}, "h": "Das Volumen ist Grundfläche mal Höhe. Stelle um: Höhe = Volumen : Grundfläche.", "w": "h = 720 : 48 = 15 cm. Doppelte Höhe: 30 cm. V = 48 · 30 = 1 440 cm³.", "form": "lueckenweg", "zaehlt": "nein", "r": 7418}, {"l": "prisma_umstellen", "t": "prisma_umstellen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Aquarium hat die Form eines Quaders. Der Boden ist 80 cm lang und 40 cm breit. Das Aquarium fasst 96 Liter. Wie hoch ist es? Es gilt 1 Liter = 1 000 cm³."}, "o": {"wert": 30, "einheit": "cm"}, "h": "Rechne die Liter in cm³ um. Stelle dann V = G · h nach h um.", "w": "96 l = 96 000 cm³. G = 80 · 40 = 3 200 cm². h = 96 000 : 3 200 = 30 cm.", "form": "anwenden", "zaehlt": "ja", "r": 7419}, {"l": "prisma_umstellen", "t": "prisma_umstellen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein gerades Prisma hat die Grundfläche 45 cm² und die Höhe 12 cm. Ein zweites gerades Prisma hat dasselbe Volumen. Seine Grundfläche ist ein Quadrat und seine Höhe ist 15 cm. Wie lang ist eine Seite dieses Quadrats?"}, "o": {"wert": 6, "einheit": "cm"}, "h": "Berechne zuerst das Volumen. Daraus folgt die Grundfläche des zweiten Prismas.", "w": "V = 45 · 12 = 540 cm³. Grundfläche des zweiten: 540 : 15 = 36 cm². Das Quadrat hat die Seite 6 cm, denn 6 · 6 = 36.", "form": "umkehren", "zaehlt": "ja", "r": 7420}, {"l": "zylinder_volumen", "t": "zylinder_volumen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Konservendose ist ein Zylinder mit dem Radius 4 cm und der Höhe 10 cm. Die Grundfläche ist ① · π cm². Das Volumen ist ② · π cm³. Mit π ≈ 3 ist das Volumen etwa ③ cm³.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [16, 160, 480]}, "h": "Die Grundfläche ist ein Kreis: Radius mal Radius mal π.", "w": "G = π · 4² = 16π cm². V = 16π · 10 = 160π cm³. Mit π ≈ 3: 480 cm³.", "form": "lueckenweg", "zaehlt": "nein", "r": 7421}, {"l": "zylinder_volumen", "t": "zylinder_volumen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Zylinder hat den Radius 5 cm und die Höhe 12 cm. Berechne sein Volumen in cm³ auf ganze Zahlen gerundet auf zwei Wegen. Weg A: mit π ≈ 3,14. Weg B: mit der π-Taste des Taschenrechners. Beide Wege führen auf dieselbe ganze Zahl. Welchen Wert erhältst du?"}, "o": {"wert": 942, "einheit": "cm³"}, "h": "Beide Wege dürfen sich nur in der Rundung unterscheiden.", "w": "Weg A: 3,14 · 25 · 12 = 942. Weg B: π · 25 · 12 ≈ 942,48, gerundet 942. Das Volumen beträgt etwa 942 cm³.", "form": "zwei_wege", "zaehlt": "ja", "r": 7422}, {"l": "zylinder_volumen", "t": "zylinder_volumen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Zylinder ist 10 cm hoch. Sein Volumen beträgt etwa 785 cm³. Wie groß ist sein Radius in cm? Runde auf ganze cm."}, "o": {"wert": 5, "einheit": "cm"}, "h": "Stelle V = π · r² · h nach r² um. Welche Zahl mal sich selbst gibt das?", "w": "r² = 785 : (π · 10) ≈ 25. Also r = 5 cm. Probe: π · 25 · 10 ≈ 785.", "form": "umkehren", "zaehlt": "ja", "r": 7423}, {"l": "zylinder_oberflaeche", "t": "zylinder_oberflaeche", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Zylinder hat den Radius 3 cm und die Höhe 8 cm. Eine Grundfläche ist ① · π cm² groß. Der Mantel ist ein Rechteck mit der Höhe 8 cm und dem Kreisumfang als Länge. Er ist ② · π cm² groß. Die Oberfläche ist ③ · π cm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 48, 66]}, "h": "Der Kreisumfang ist 2 mal π mal Radius. Die Oberfläche hat zwei Grundflächen und einen Mantel.", "w": "G = 9π. Mantel: 2π · 3 · 8 = 48π. O = 2 · 9π + 48π = 66π cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 7424}, {"l": "zylinder_oberflaeche", "t": "zylinder_oberflaeche", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Das Netz eines Zylinders besteht aus zwei Kreisen und einem Rechteck, wie die Tabelle zeigt. Welche Formel gibt die Oberfläche eines Zylinders mit Radius r und Höhe h an?", "grafik": {"typ": "tabelle", "kopf": ["Teil des Netzes", "Anzahl", "Fläche je Stück"], "zeilen": [["Kreis mit Radius r", "2", "π · r²"], ["Rechteck (Mantel)", "1", "2 · π · r · h"]]}}, "a": ["2πr² + 2πrh", "πr² + 2πrh", "2πr² + πrh", "2πr + 2πh"], "o": {"index": 0}, "h": "Zähle die Flächen der Tabelle zusammen: Anzahl mal Fläche je Stück.", "w": "Zwei Kreise: 2 · π · r². Das Rechteck hat die Länge 2πr und die Breite h: 2πrh. Zusammen 2πr² + 2πrh.", "form": "bruecke", "zaehlt": "ja", "r": 7425}, {"l": "zylinder_oberflaeche", "t": "zylinder_oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine gerade zylinderförmige Blechdose hat den Durchmesser 8 cm und die Höhe 11 cm. Sie hat Boden, Deckel und Mantel. Wie viel Quadratzentimeter Blech braucht man für eine Dose, wenn nichts verschnitten wird? Rechne mit der π-Taste und runde auf ganze cm²."}, "o": {"wert": 377, "einheit": "cm²"}, "h": "Der Radius ist halb so groß wie der Durchmesser.", "w": "r = 4 cm. Zwei Kreise: 2 · π · 16 ≈ 100,5. Mantel: 2 · π · 4 · 11 ≈ 276,5. O ≈ 377,0 cm², gerundet 377 cm². (Mit π ≈ 3,14 erhält man 376,8, gerundet ebenfalls 377.)", "form": "anwenden", "zaehlt": "ja", "r": 7426}, {"l": "sach", "t": "sach", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Schwimmbecken ist ein gerades Prisma mit einer rechteckigen Grundfläche von 10 m mal 5 m. Es ist 2 m tief. Es fasst ① m³. In einen Kubikmeter passen 1 000 Liter, also fasst es ② Liter. Eine Pumpe schafft 4 000 Liter in der Stunde. Das Füllen dauert ③ Stunden.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [100, 100000, 25]}, "h": "Volumen = Länge mal Breite mal Tiefe. Dann in Liter umrechnen.", "w": "V = 10 · 5 · 2 = 100 m³ = 100 000 l. 100 000 : 4 000 = 25. Das Füllen dauert 25 Stunden.", "form": "lueckenweg", "zaehlt": "nein", "r": 7427}, {"l": "sach", "t": "sach", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du willst wissen, wie viel Erde in einen zylinderförmigen Blumenkübel passt. Der Kübel hat 40 cm Durchmesser und ist 30 cm hoch. Welcher Rechenweg ist richtig?"}, "a": ["V = π · 40² · 30", "V = 2 · π · 20 · 30", "Radius 20 cm nehmen: V = π · 20² · 30", "V = π · 20 · 30"], "o": {"index": 2}, "h": "Das Volumen ist Grundfläche mal Höhe. Welche Größe steckt in der Kreisfläche?", "w": "r = 40 : 2 = 20 cm. G = π · 20² . V = π · 400 · 30 ≈ 37 699 cm³, also etwa 37,7 Liter.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 7428}, {"l": "sach", "t": "sach", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Ein zylinderförmiger Wassertank hat den Durchmesser 2 m und die Höhe 3 m. Eine Pumpe füllt ihn mit 500 Litern in der Minute. Wie viele Minuten dauert es, den leeren Tank ganz zu füllen? Runde auf ganze Minuten. Es gilt 1 m³ = 1 000 Liter."}, "o": {"wert": 19, "einheit": "min"}, "h": "Berechne erst das Volumen in m³. Rechne dann in Liter um.", "w": "r = 1 m. V = π · 1² · 3 ≈ 9,42 m³ ≈ 9 425 l. 9 425 : 500 ≈ 18,85. Es dauert etwa 19 Minuten.", "form": "anwenden", "zaehlt": "ja", "r": 7429}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt zwei gerade Kreiszylinder. Wie verhält sich das Volumen von Zylinder B zu dem von Zylinder A?", "grafik": {"typ": "tabelle", "kopf": ["", "Radius", "Höhe"], "zeilen": [["Zylinder A", "2 cm", "9 cm"], ["Zylinder B", "6 cm", "3 cm"]]}}, "a": ["9-mal so groß", "gleich groß", "3-mal so groß", "1/3 so groß"], "o": {"index": 2}, "h": "Der Radius geht quadratisch ein, die Höhe nur einfach. Rechne beide Volumina aus oder vergleiche die Faktoren.", "w": "A: π · 2² · 9 = 36π. B: π · 6² · 3 = 108π. 108π : 36π = 3. Der Radius wird 3-mal so groß (Faktor 9), die Höhe 3-mal so klein (Faktor 1/3). Zusammen 9 · 1/3 = 3.", "form": "bruecke", "zaehlt": "ja", "r": 7430}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein gerades Prisma hat die Grundfläche 20 cm² und die Höhe 6 cm. Man verändert es: Die Grundfläche wird 3-mal so groß, die Höhe halb so groß. Wie groß ist das neue Volumen? Weg A: neue Grundfläche und neue Höhe ausrechnen, dann das Volumen. Weg B: das alte Volumen mit 3 und mit 1/2 verrechnen."}, "o": {"wert": 180, "einheit": "cm³"}, "h": "Beide Wege müssen dasselbe Volumen ergeben.", "w": "Weg A: G = 60 cm², h = 3 cm, V = 180 cm³. Weg B: altes V = 120 cm³, 120 · 3 : 2 = 180 cm³.", "form": "zwei_wege", "zaehlt": "ja", "r": 7431}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim behauptet: Verdoppelt man bei einem Zylinder den Radius und lässt die Höhe gleich, wird das Volumen doppelt so groß. Zeile 1: Das Volumen ist V = π · r² · h. Zeile 2: Mit dem Radius 2r steht dort V = π · 2r · h = 2πrh. Zeile 3: Also ist das neue Volumen doppelt so groß. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Was passiert mit r², wenn r verdoppelt wird? Probe mit r = 1 und r = 2.", "w": "(2r)² = 4r². Das neue Volumen ist π · 4r² · h = 4πr²h, also 4-mal so groß. Probe: r = 1 gibt π · h, r = 2 gibt 4π · h.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7432}]$auf$::jsonb),
    (111, 'terme.potenzgesetze_natuerlich', 166, 15, $auf$[{"l": "mal_gleiche_basis", "t": "mal_gleiche_basis", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vereinfache 3⁴ · 3⁵ zu einer Potenz mit der Basis 3. Die Hochzahl ist dann ①. Multiplizierst du dieses Ergebnis noch mit 3², hat die Potenz die Hochzahl ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 11]}, "h": "Gleiche Basis beim Malnehmen: Was passiert mit den Hochzahlen?", "w": "3⁴ · 3⁵ = 3⁹, denn 4 + 5 = 9. Mit 3² dazu: 3¹¹, denn 9 + 2 = 11.", "form": "lueckenweg", "zaehlt": "nein", "r": 7167}, {"l": "mal_gleiche_basis", "t": "mal_gleiche_basis", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 2⁴ · 2³ auf zwei Wegen. Weg A: beide Potenzen einzeln ausrechnen und dann malnehmen. Weg B: erst die Hochzahlen zusammenfassen und dann die Potenz ausrechnen. Welchen Wert hat das Produkt?"}, "o": {"wert": 128}, "h": "Beide Wege müssen denselben Wert ergeben.", "w": "Weg A: 16 · 8 = 128. Weg B: 2⁷ = 128.", "form": "zwei_wege", "zaehlt": "ja", "r": 7168}, {"l": "mal_gleiche_basis", "t": "mal_gleiche_basis", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vereinfacht a³ · a⁴ · a². Die Zeilen bauen aufeinander auf. Zeile 1: Die Basis ist überall a, die Hochzahlen werden malgenommen: 3 · 4 · 2 = 24. Zeile 2: Also ist a³ · a⁴ · a² = a²⁴. Zeile 3: Das Ergebnis lautet a²⁴. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Was geschieht mit den Hochzahlen, wenn man Potenzen mit gleicher Basis malnimmt? Probe mit a = 2 und kleinen Hochzahlen: 2² · 2³.", "w": "Beim Malnehmen werden die Hochzahlen addiert: 3 + 4 + 2 = 9. Richtig ist a⁹. Probe mit 2² · 2³ = 4 · 8 = 32 = 2⁵ und nicht 2⁶.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7169}, {"l": "gleicher_exponent", "t": "gleicher_exponent", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Berechne 24³ : 6³ geschickt. Beide Potenzen haben dieselbe Hochzahl. Du teilst zuerst die Basen und erhältst ①. Dieses Ergebnis nimmst du hoch drei und erhältst ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 64]}, "h": "Bei gleichen Hochzahlen darfst du die Basen zuerst teilen.", "w": "24 : 6 = 4. 4³ = 64. Probe: 24³ : 6³ = 13824 : 216 = 64.", "form": "lueckenweg", "zaehlt": "nein", "r": 7170}, {"l": "gleicher_exponent", "t": "gleicher_exponent", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Das Produkt 2 · 2 · 2 · 2 · 5 · 5 · 5 · 5 soll als eine einzige Potenz geschrieben werden. Welche Potenz ist das?"}, "a": ["7⁴", "10⁴", "10⁸", "10¹⁶"], "o": {"index": 1}, "h": "Es gibt gleich viele Faktoren 2 und 5. Fasse je einen Faktor 2 und einen Faktor 5 zusammen.", "w": "Vier Paare 2 · 5 = 10. Also 10 · 10 · 10 · 10 = 10⁴. Probe: 16 · 625 = 10 000.", "form": "bruecke", "zaehlt": "ja", "r": 7171}, {"l": "gleicher_exponent", "t": "gleicher_exponent", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Für welche Zahl a gilt a³ = 2³ · 7³?"}, "o": {"wert": 14}, "h": "Wenn die Hochzahlen gleich sind, darfst du die Basen malnehmen.", "w": "2³ · 7³ = (2 · 7)³ = 14³. Also ist a = 14. Probe: 8 · 343 = 2 744 = 14³.", "form": "umkehren", "zaehlt": "ja", "r": 7172}, {"l": "potenz_von_potenz", "t": "potenz_von_potenz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vereinfache (2³)⁴ zu einer Potenz 2^k. Die Hochzahlen werden verrechnet: k = ①. Der Wert der Potenz 2^k ist ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 4096]}, "h": "Eine Potenz wird noch einmal hoch genommen. Was geschieht mit den Hochzahlen?", "w": "(2³)⁴ = 2³ · 2³ · 2³ · 2³ = 2¹². 2¹² = 4 096.", "form": "lueckenweg", "zaehlt": "nein", "r": 7173}, {"l": "potenz_von_potenz", "t": "potenz_von_potenz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne (3²)³ auf zwei Wegen. Weg A: erst die Klammer 3² ausrechnen und das Ergebnis hoch 3 nehmen. Weg B: die Hochzahlen verrechnen und dann die Potenz ausrechnen. Welchen Wert hat (3²)³?"}, "o": {"wert": 729}, "h": "Beide Wege müssen denselben Wert ergeben.", "w": "Weg A: 9³ = 729. Weg B: 3⁶ = 729.", "form": "zwei_wege", "zaehlt": "ja", "r": 7174}, {"l": "potenz_von_potenz", "t": "potenz_von_potenz", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Der Term (x⁴)² soll als Produkt geschrieben werden. Welches Produkt ist dasselbe wie (x⁴)²?"}, "a": ["x⁴ · x²", "x⁴ + x⁴", "8x", "x⁴ · x⁴"], "o": {"index": 3}, "h": "Hoch 2 heißt: Der Inhalt der Klammer kommt zweimal als Faktor vor.", "w": "(x⁴)² = x⁴ · x⁴ = x⁸.", "form": "bruecke", "zaehlt": "ja", "r": 7175}, {"l": "geteilt_gleiche_basis", "t": "geteilt_gleiche_basis", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vereinfache 7⁹ : 7⁴ zu einer Potenz mit der Basis 7. Die Hochzahl ist dann ①. Teilst du das Ergebnis noch durch 7², hat die Potenz die Hochzahl ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 3]}, "h": "Gleiche Basis beim Teilen: Was passiert mit den Hochzahlen?", "w": "7⁹ : 7⁴ = 7⁵, denn 9 − 4 = 5. Noch durch 7²: 7³, denn 5 − 2 = 3.", "form": "lueckenweg", "zaehlt": "nein", "r": 7176}, {"l": "geteilt_gleiche_basis", "t": "geteilt_gleiche_basis", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In der Rechnung 5^k : 5⁴ = 5⁷ fehlt die Hochzahl k. Wie groß ist k?"}, "o": {"wert": 11}, "h": "Beim Teilen werden die Hochzahlen subtrahiert. Rechne rückwärts.", "w": "k − 4 = 7, also k = 11. Probe: 5¹¹ : 5⁴ = 5⁷.", "form": "umkehren", "zaehlt": "ja", "r": 7177}, {"l": "geteilt_gleiche_basis", "t": "geteilt_gleiche_basis", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vereinfacht a⁸ : a³ : a für a ≠ 0. Die Zeilen bauen aufeinander auf. Zeile 1: a⁸ : a³ = a⁵, denn 8 − 3 = 5. Zeile 2: a⁵ : a = a⁵, weil a keine Hochzahl hat. Zeile 3: Das Ergebnis lautet a⁵. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welche Hochzahl hat a, wenn nichts dransteht? Probe mit a = 2.", "w": "a ist dasselbe wie a¹. Also a⁵ : a¹ = a⁴. Probe mit a = 2: 32 : 2 = 16 = 2⁴.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7178}, {"l": "anwenden", "t": "anwenden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Zelle teilt sich jede Stunde in zwei Zellen. Nach 3 Stunden sind aus einer Zelle 2³ Zellen geworden. Jede dieser Zellen vermehrt sich in 7 weiteren Stunden genauso weiter. Wie viele Zellen sind es dann insgesamt?"}, "o": {"wert": 1024, "einheit": "Zellen"}, "h": "Jede Zelle wird in 7 Stunden zu 2⁷ Zellen. Wie viele solcher Gruppen gibt es?", "w": "Es gibt 2³ = 8 Zellen. Jede wird zu 2⁷ = 128. Insgesamt 8 · 128 = 1 024 = 2¹⁰ Zellen.", "form": "anwenden", "zaehlt": "ja", "r": 7179}, {"l": "anwenden", "t": "anwenden", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst 5⁶ : 5² berechnen. Welcher Weg ist richtig?"}, "a": ["Die Hochzahlen subtrahieren: 5⁴ = 625.", "Die Hochzahlen teilen: 5³ = 125.", "Die Basen teilen und die Hochzahlen subtrahieren: 1⁴ = 1.", "Die Hochzahlen addieren: 5⁸ = 390 625."], "o": {"index": 0}, "h": "Beim Teilen gleicher Basen bleibt die Basis. Nur die Hochzahlen werden verrechnet.", "w": "5⁶ : 5² = 5⁶⁻² = 5⁴ = 625. Probe: 15 625 : 25 = 625.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 7180}, {"l": "anwenden", "t": "anwenden", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Würfel hat die Kantenlänge 2⁴ cm. Das Volumen ist Kante mal Kante mal Kante. Es lässt sich als Potenz 2^k cm³ schreiben. Wie groß ist k?"}, "o": {"wert": 12}, "h": "Schreibe das Volumen als (2⁴)³ und verrechne die Hochzahlen.", "w": "V = (2⁴)³ = 2⁴ · 2⁴ · 2⁴ = 2¹². Das sind 4 096 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 7181}]$auf$::jsonb),
    (112, 'terme.potenzgesetze_ganzzahlig', 112, 15, $auf$[{"l": "warum_gilt", "t": "warum_gilt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Setze das Muster fort: 4⁴ = 256 und 4³ = 64. Bei jedem Schritt nach rechts wird durch 4 geteilt. Dann ist 4² = ① und die Summe 4¹ + 4⁰ ist ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [16, 5]}, "h": "Teile den Wert immer wieder durch die Basis. Wie oft musst du teilen, bis du bei der Hochzahl 0 bist?", "w": "64 : 4 = 16 für 4². Dann 16 : 4 = 4 für 4¹ und 4 : 4 = 1 für 4⁰. Also 4⁰ = 1 und 4¹ + 4⁰ = 4 + 1 = 5.", "form": "lueckenweg", "zaehlt": "nein", "r": 7113}, {"l": "warum_gilt", "t": "warum_gilt", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt das Muster der Potenzen von 2. Bei jedem Schritt nach rechts wird der Wert halbiert. Welcher Wert gehört zu 2⁻²?", "grafik": {"typ": "tabelle", "kopf": ["2³", "2²", "2¹", "2⁰", "2⁻¹", "2⁻²"], "zeilen": [["8", "4", "2", "1", "?", "?"]]}}, "a": ["−4", "1/2", "1/4", "−1/4"], "o": {"index": 2}, "h": "Setze das Halbieren in der Tabelle von links nach rechts fort.", "w": "2⁰ = 1, 2⁻¹ = 1/2, 2⁻² = 1/4. Bei jedem Schritt nach rechts wird halbiert.", "form": "bruecke", "zaehlt": "ja", "r": 7114}, {"l": "warum_gilt", "t": "warum_gilt", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Für welche ganze Zahl k gilt 3^k = 1/27?"}, "o": {"wert": -3}, "h": "Schreibe 27 als Potenz von 3. Eine negative Hochzahl bedeutet: Kehrwert.", "w": "27 = 3³. Also 1/27 = 1/3³ = 3⁻³. Probe: 3⁻³ = 1/27.", "form": "umkehren", "zaehlt": "ja", "r": 7115}, {"l": "gleiche_basis_ganz", "t": "gleiche_basis_ganz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vereinfache z⁴ · z⁻⁹ für z ≠ 0 zu z^k. Die Hochzahlen werden addiert: k = ①. Multiplizierst du das Ergebnis noch mit z⁶, ergibt sich die Hochzahl ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-5, 1]}, "h": "Gleiche Basis beim Malnehmen: Hochzahlen addieren. Achte auf das Vorzeichen.", "w": "4 + (−9) = −5, also z⁻⁵. Mit z⁶: −5 + 6 = 1, also z¹ = z.", "form": "lueckenweg", "zaehlt": "nein", "r": 7116}, {"l": "gleiche_basis_ganz", "t": "gleiche_basis_ganz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 2⁵ · 2⁻² auf zwei Wegen. Weg A: schreibe 2⁻² als Bruch und rechne 32 mal diesen Bruch. Weg B: addiere die Hochzahlen und berechne die Potenz. Welchen Wert hat das Produkt?"}, "o": {"wert": 8}, "h": "Beide Wege müssen denselben Wert ergeben.", "w": "Weg A: 2⁻² = 1/4. 32 · 1/4 = 8. Weg B: 5 + (−2) = 3, also 2³ = 8.", "form": "zwei_wege", "zaehlt": "ja", "r": 7117}, {"l": "gleiche_basis_ganz", "t": "gleiche_basis_ganz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Haar ist 10⁻⁴ m dick. Eine Zelle ist 10⁻⁶ m breit. Wie viele Zellen passen nebeneinander in die Dicke eines Haars?"}, "o": {"wert": 100, "einheit": "Zellen"}, "h": "Teile die Dicke des Haars durch die Breite einer Zelle. Subtrahiere die Hochzahlen.", "w": "10⁻⁴ : 10⁻⁶ = 10⁻⁴⁻⁽⁻⁶⁾ = 10² = 100. Es passen 100 Zellen nebeneinander.", "form": "anwenden", "zaehlt": "ja", "r": 7118}, {"l": "exponent_und_potenz", "t": "exponent_und_potenz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vereinfache (2⁻³)⁴ zu einer Potenz 2^k. Die Hochzahlen werden verrechnet: k = ①. Der Wert der Potenz ist dann 1/②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-12, 4096]}, "h": "Eine Potenz wird noch einmal hoch genommen. Was geschieht mit den Hochzahlen?", "w": "(2⁻³)⁴ = 2⁻¹². Das ist 1/2¹² = 1/4 096.", "form": "lueckenweg", "zaehlt": "nein", "r": 7119}, {"l": "exponent_und_potenz", "t": "exponent_und_potenz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Für welche ganze Zahl k gilt (a⁻²)^k = a⁻¹⁰ für alle Zahlen a ≠ 0?"}, "o": {"wert": 5}, "h": "Beim Hoch-Nehmen werden die Hochzahlen malgenommen. Rechne rückwärts.", "w": "(−2) · k = −10, also k = 5. Probe: (a⁻²)⁵ = a⁻¹⁰.", "form": "umkehren", "zaehlt": "ja", "r": 7120}, {"l": "exponent_und_potenz", "t": "exponent_und_potenz", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Der Bruch 1/(a³) soll mit einer negativen Hochzahl geschrieben werden. Welche Schreibweise ist richtig (a ≠ 0)?"}, "a": ["−a³", "(−a)³", "a⁻³", "3a⁻¹"], "o": {"index": 2}, "h": "Eine negative Hochzahl bedeutet: Kehrwert.", "w": "1/a³ = a⁻³. Probe mit a = 2: 1/8 = 2⁻³.", "form": "bruecke", "zaehlt": "ja", "r": 7121}, {"l": "terme_vereinfachen", "t": "terme_vereinfachen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du sollst a⁵ : a⁻² vereinfachen (a ≠ 0). Welcher Weg ist richtig?"}, "a": ["Hochzahlen subtrahieren: 5 − (−2) = 7, also a⁷.", "Hochzahlen subtrahieren: 5 − 2 = 3, also a³.", "Hochzahlen addieren: 5 + (−2) = 3, also a³.", "Hochzahlen malnehmen: 5 · (−2) = −10, also a⁻¹⁰."], "o": {"index": 0}, "h": "Beim Teilen wird die Hochzahl des Teilers abgezogen. Achte dabei auf das Vorzeichen.", "w": "a⁵ : a⁻² = a⁵⁻⁽⁻²⁾ = a⁷. Probe mit a = 2: 32 : 1/4 = 128 = 2⁷.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 7122}, {"l": "terme_vereinfachen", "t": "terme_vereinfachen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vereinfacht (4x⁻²) · (3x⁵) für x ≠ 0. Zeile 1: Die Zahlen werden malgenommen: 4 · 3 = 12. Zeile 2: Die Hochzahlen werden addiert: x⁻² · x⁵ = x³. Zeile 3: Weil die Hochzahl −2 negativ war, ist das Ergebnis negativ: −12x³. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Was bedeutet eine negative Hochzahl für die Zahl vor x? Probe mit x = 2.", "w": "Eine negative Hochzahl macht die Zahl nicht negativ. Das Ergebnis ist 12x³. Probe mit x = 2: (4/4) · 96 = 96 und 12 · 8 = 96.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7123}, {"l": "terme_vereinfachen", "t": "terme_vereinfachen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Bakterie ist 2 · 10⁻⁶ m lang. Wie viele solche Bakterien ergeben hintereinander gelegt 1 mm? Es gilt 1 mm = 10⁻³ m."}, "o": {"wert": 500, "einheit": "Bakterien"}, "h": "Teile 10⁻³ durch 2 · 10⁻⁶. Teile die Zahlen und die Potenzen getrennt.", "w": "10⁻³ : (2 · 10⁻⁶) = (1 : 2) · 10⁻³⁺⁶ = 0,5 · 10³ = 500. Es sind 500 Bakterien.", "form": "anwenden", "zaehlt": "ja", "r": 7124}, {"l": "fehler_ganz", "t": "fehler_ganz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 4⁻² : 4⁻⁴ auf zwei Wegen. Weg A: beide Potenzen als Brüche schreiben und teilen. Weg B: die Hochzahlen subtrahieren und die Potenz berechnen. Welchen Wert erhältst du?"}, "o": {"wert": 16}, "h": "Beide Wege müssen denselben Wert ergeben.", "w": "Weg A: (1/16) : (1/256) = 256/16 = 16. Weg B: −2 − (−4) = 2, also 4² = 16.", "form": "zwei_wege", "zaehlt": "ja", "r": 7125}, {"l": "fehler_ganz", "t": "fehler_ganz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du sollst 2⁻³ + 2⁻³ berechnen. Welcher Weg ist richtig?"}, "a": ["Die Hochzahlen addieren: 2⁻⁶ = 1/64.", "Die Basen addieren: 4⁻³ = 1/64.", "Die Hochzahlen malnehmen: 2⁹ = 512.", "Beide Potenzen als Bruch schreiben: 1/8 + 1/8 = 1/4."], "o": {"index": 3}, "h": "Für Plus gibt es kein Potenzgesetz. Schreibe erst jede Potenz als Zahl.", "w": "2⁻³ = 1/8. Zwei Achtel sind 2/8 = 1/4.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 7126}, {"l": "fehler_ganz", "t": "fehler_ganz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vereinfacht 3⁻² · 3⁻³ : 3⁻¹. Die Zeilen bauen aufeinander auf. Zeile 1: Beim Malnehmen werden die Hochzahlen addiert: −2 + (−3) = −5, also 3⁻⁵. Zeile 2: Beim Teilen durch 3⁻¹ werden die Hochzahlen subtrahiert: −5 − (−1). Zeile 3: Das ergibt −5 + 1 = −4, also 3⁻⁴. Zeile 4: Weil die Hochzahl negativ ist, gilt 3⁻⁴ = −81. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Was bedeutet eine negative Hochzahl für den Wert der Potenz? Prüfe mit 2⁻¹.", "w": "Eine negative Hochzahl bedeutet den Kehrwert, nicht eine negative Zahl. 3⁻⁴ = 1/3⁴ = 1/81. Probe: 2⁻¹ = 1/2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7127}]$auf$::jsonb),
    (305, 'terme.umformen_teil2', 789, 12, $auf$[{"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Multipliziere aus: (x + 5)(x + 3). Es entstehen vier Produkte. Fasse die beiden Produkte mit x zusammen. Das Ergebnis lautet x² + ①x + ②. Setzt du in dieses Ergebnis x = 1 ein, erhältst du ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 15, 24]}, "h": "Jedes Glied der ersten Klammer wird mit jedem Glied der zweiten Klammer malgenommen.", "w": "x² + 3x + 5x + 15 = x² + 8x + 15. Für x = 1: 1 + 8 + 15 = 24.", "form": "lueckenweg", "zaehlt": "nein", "r": 7790}, {"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne (x + 3)(x − 2) für x = 5 auf zwei Wegen. Weg A: erst ausmultiplizieren (das gibt x² + x − 6), dann x = 5 einsetzen. Weg B: erst x = 5 in beide Klammern einsetzen, dann malnehmen. Welchen Wert erhältst du?"}, "o": {"wert": 24}, "h": "Beide Wege müssen denselben Wert ergeben.", "w": "Weg A: 25 + 5 − 6 = 24. Weg B: 8 · 3 = 24.", "form": "zwei_wege", "zaehlt": "ja", "r": 7791}, {"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zerlegt ein Rechteck in vier Teilflächen. Oben stehen die beiden Teile der Länge, links die der Breite. Welches Produkt gibt die ganze Fläche?", "grafik": {"typ": "tabelle", "kopf": ["·", "x", "+2"], "zeilen": [["x", "x²", "2x"], ["+5", "5x", "10"]]}}, "a": ["(x + 5)(x + 10)", "(x + 7)(x + 3)", "x(x + 2) + 5", "(x + 5)(x + 2)"], "o": {"index": 3}, "h": "Länge mal Breite: Welche zwei Teile bilden die Länge, welche die Breite?", "w": "Länge: x + 2. Breite: x + 5. Fläche: (x + 5)(x + 2) = x² + 2x + 5x + 10 = x² + 7x + 10.", "form": "bruecke", "zaehlt": "ja", "r": 7792}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Klammere den größten gemeinsamen Faktor aus: 12x + 18. Der Faktor vor der Klammer ist ①. In der Klammer steht ②x + ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 2, 3]}, "h": "Welche größte Zahl teilt 12 und 18 ohne Rest?", "w": "Der größte gemeinsame Teiler ist 6. 12x : 6 = 2x und 18 : 6 = 3. Probe: 6(2x + 3) = 12x + 18.", "form": "lueckenweg", "zaehlt": "nein", "r": 7793}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 6 · 17 + 6 · 13 auf zwei Wegen. Weg A: beide Produkte einzeln ausrechnen und addieren. Weg B: den Faktor 6 ausklammern und die Summe in der Klammer bilden. Was kommt heraus?"}, "o": {"wert": 180}, "h": "Beide Wege müssen dasselbe ergeben. Welcher ist kürzer?", "w": "Weg A: 102 + 78 = 180. Weg B: 6 · (17 + 13) = 6 · 30 = 180.", "form": "zwei_wege", "zaehlt": "ja", "r": 7794}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Verein bestellt 25 T-Shirts zu 8,50 € das Stück und 25 Mützen zu 6,50 € das Stück. Wie viel Euro kostet die ganze Bestellung? Klammere geschickt aus."}, "o": {"wert": 375, "einheit": "€"}, "h": "Beide Posten haben dieselbe Anzahl. Was kannst du ausklammern?", "w": "25 · 8,50 + 25 · 6,50 = 25 · (8,50 + 6,50) = 25 · 15 = 375. Die Bestellung kostet 375 €.", "form": "anwenden", "zaehlt": "ja", "r": 7795}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Multipliziere mit der 2. binomischen Formel aus: (2a − 3)². Das Ergebnis lautet ①a² − ②a + ③. Setzt du in dieses Ergebnis a = 5 ein, erhältst du ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 12, 9, 49]}, "h": "Die Zahl vor a wird mitquadriert. Das mittlere Glied ist das doppelte Produkt.", "w": "(2a)² = 4a². 2 · 2a · 3 = 12a. 3² = 9. Ergebnis: 4a² − 12a + 9. Für a = 5: 100 − 60 + 9 = 49. Probe: (10 − 3)² = 49.", "form": "lueckenweg", "zaehlt": "nein", "r": 7796}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Für welche Zahl b gilt 9x² + bx + 25 = (3x + 5)² für alle Zahlen x?"}, "o": {"wert": 30}, "h": "Multipliziere (3x + 5)² aus. Das mittlere Glied ist das doppelte Produkt.", "w": "(3x + 5)² = 9x² + 2 · 3x · 5 + 25 = 9x² + 30x + 25. Das gilt für alle Zahlen x, wenn b = 30 ist.", "form": "umkehren", "zaehlt": "ja", "r": 7797}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zerlegt ein Quadrat mit der Seitenlänge a + 3 in vier Teilflächen. Welcher Term gibt die Gesamtfläche an?", "grafik": {"typ": "tabelle", "kopf": ["·", "a", "+3"], "zeilen": [["a", "a²", "3a"], ["+3", "3a", "9"]]}}, "a": ["a² + 9", "a² + 6a + 9", "a² + 3a + 9", "a² + 6a + 6"], "o": {"index": 1}, "h": "Zähle alle vier Teilflächen zusammen.", "w": "a² + 3a + 3a + 9 = a² + 6a + 9. Das ist (a + 3)².", "form": "bruecke", "zaehlt": "ja", "r": 7798}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst die Gleichung (x + 4)² = x² + 40. Zeile 1: (x + 4)² = x² + 8x + 16, also x² + 8x + 16 = x² + 40 Zeile 2: x² auf beiden Seiten abziehen: 8x + 16 = 40 Zeile 3: 8x = 40 + 16 = 56, also x = 7 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wie bringst du die 16 auf die rechte Seite? Mach die Probe mit x = 7.", "w": "Die 16 muss abgezogen werden: 8x = 40 − 16 = 24, also x = 3. Probe: 7² = 49 und 9 + 40 = 49.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 7799}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Bei einem quadratischen Platz wird jede Seite um 3 m länger. Dadurch wächst die Fläche um 51 m². Wie lang war eine Seite vorher?"}, "o": {"wert": 7, "einheit": "m"}, "h": "Die alte Seite ist a. Die neue Fläche ist (a + 3)². Die Zunahme ist (a + 3)² − a².", "w": "(a + 3)² − a² = 6a + 9. Aus 6a + 9 = 51 folgt 6a = 42, also a = 7. Probe: 10² − 7² = 100 − 49 = 51.", "form": "anwenden", "zaehlt": "ja", "r": 7800}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Gleichung (x + 3)² = x² + 4x + a hat die Lösung x = 4. Wie groß ist die Zahl a?"}, "o": {"wert": 17}, "h": "Setze x = 4 in beide Seiten ein.", "w": "Links: (4 + 3)² = 49. Rechts: 16 + 16 + a = 32 + a. Aus 49 = 32 + a folgt a = 17.", "form": "umkehren", "zaehlt": "ja", "r": 7801}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 183 then fehler := fehler || ('zusammen ' || gesamt || ' statt 183')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (3, 5, 7, 20, 31, 34, 72, 94, 111, 112, 305) group by 1 order by 1;
